// Generated by Upskale Studio. Do not edit this file directly.
//
// How a page import is fetched, on the server only (data.ts's server
// function): from the tenant API or an external one, with any key from the
// website's environment (SECRET_<NAME>), never from the page or the browser.

export interface FetchSpec {
  source: "tenant" | "external";
  /** Tenant: the API path, its {params} filled in; the others go in the query. */
  path?: string;
  query?: string[];
  /** External: the address, its {params} filled in. */
  url?: string;
  /** A dotted path to the part the page reads. */
  select?: string;
  secret?: string;
  secretHeader?: string;
  /** What the page reads of it (the compiler's), when not all of it. */
  fields?: Fields;
}

/**
 * Only the fields read: of an object, those it has; of a list, of each
 * item; a text or a number as it is. No fields is all of it.
 */
export function project(value: unknown, fields: Fields | undefined): unknown {
  if (!fields) return value;
  if (Array.isArray(value)) return value.map((item) => project(item, fields));
  if (value == null || typeof value !== "object") return value;
  const out: Record<string, unknown> = {};
  for (const [key, sub] of Object.entries(fields)) {
    if (!Object.prototype.hasOwnProperty.call(value, key)) continue;
    const field = (value as Record<string, unknown>)[key];
    out[key] = sub === true ? field : project(field, sub);
  }
  return out;
}

function fill(template: string, params: Record<string, string>, used: Set<string>) {
  return template.replace(/\{([A-Za-z_][A-Za-z0-9_-]*)\}/g, (_, name: string) => {
    used.add(name);
    return encodeURIComponent(params[name] ?? "");
  });
}

function pick(value: unknown, path: string | undefined): unknown {
  if (!path) return value;
  let current: any = value;
  for (const key of path.split(".")) {
    if (current == null) return null;
    current = Array.isArray(current) && /^\d+$/.test(key) ? current[Number(key)] : current[key];
  }
  return current ?? null;
}

export async function fetchSpec(spec: FetchSpec, params: Record<string, string>, tenantApi: string): Promise<any> {
  // any: JSON from the network, read by the page as it comes.
  const used = new Set<string>();
  let address: URL;
  const headers: Record<string, string> = { Accept: "application/json" };
  if (spec.source === "tenant") {
    address = new URL(tenantApi.replace(/\/+$/, "") + "/api/v1" + fill(spec.path ?? "/", params, used));
    for (const name of spec.query ?? []) if (params[name]) address.searchParams.set(name, params[name]);
  } else {
    address = new URL(fill(spec.url ?? "", params, used));
    // Parameters the address doesn't name go in its query string.
    for (const [name, value] of Object.entries(params)) if (!used.has(name)) address.searchParams.set(name, value);
    if (spec.secret) {
      const secret = process.env["SECRET_" + spec.secret];
      if (!secret) throw new Error(`The website's secret ${spec.secret} isn't set.`);
      const header = spec.secretHeader || "Authorization";
      headers[header] = header.toLowerCase() === "authorization" ? "Bearer " + secret : secret;
    }
  }
  const response = await fetch(address, { headers, signal: AbortSignal.timeout(8000) });
  if (response.status === 404) throw new Error("404: not found");
  if (!response.ok) throw new Error(`The data source answered ${response.status}.`);
  return pick(await response.json(), spec.select);
}

export interface ComponentProps {
  variant?: string;
  options?: Record<string, unknown>;
  actions?: Record<string, Action>;
}

// ------------------------------------------------------------ configuration

interface Settings {
  apiBaseUrl: string;
  storeId: string;
  entryPath: string;
  routePaths: Record<string, string>;
  /** What the pages fetch themselves (their Data settings): "menu", "cities". */
  pageResources?: string[];
}

/**
 * Called by router.tsx as each router is made: once in the browser, once per
 * request on the server. The storefront holds a visitor's cart and session,
 * so on the server it is only ever read empty, never acted on.
 */
export function configure(next: Settings, queries: QueryClient) {
  settings = next;
  storefront = new Storefront(next.apiBaseUrl, next.storeId, queries);
  // What the server refused in the cart: shown as any message is.
  storefront.onProblem = (message) => notice(message);
  // Pages that import the menu fetch it themselves: a chosen store loads only the store.
  storefront.loadsMenu = !next.pageResources?.includes("menu");
}

/**
 * A page's imports as bindings: one not fetched (no store chosen yet)
 * leaves the built-in of its name; an imported menu brings its store,
 * categories and the products shown online, as the storefront's own does.
 */
export function importedBindings(data: Json | undefined): Json {
  const out: Json = {};
  for (const [name, value] of Object.entries(data ?? {})) if (value != null) out[name] = value;
  const menu = out.menu;
  if (menu && typeof menu === "object" && Array.isArray(menu.categories)) {
    const categories = menu.categories as Json[];
    out.categories ??= categories;
    out.category ??= categories[0] ?? null;
    if (menu.store) out.store ??= menu.store;
    out.products ??= [
      ...categories.flatMap((category) => (Array.isArray(category?.products) ? category.products : [])),
      ...(Array.isArray(menu.uncategorised) ? menu.uncategorised : []),
    ].filter((product: Json) => product?.is_available_online !== false);
  }
  return out;
}

export function useRouter(next: AppRouter) {
  router = next;
}

// ------------------------------------------------------------------ values

export function truthy(value: unknown): boolean {
  return value != null && value !== false && value !== "" && value !== 0;
}

export function text(value: unknown): string {
  if (value == null) return "";
  if (typeof value === "number") return Number.isInteger(value) ? String(value) : String(value);
  return String(value);
}

/** Anything that isn't a number counts as 0, as in the preview. */
export function num(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

export function read(value: unknown, path: unknown[]): any {
  let current: any = value;
  for (const key of path) {
    if (typeof key === "string" && unsafeKeys.has(key)) return null;
    if (Array.isArray(current)) {
      if (typeof key === "number" && Number.isInteger(key) && key >= 0 && key < current.length) current = current[key];
      else if (key === "length") current = current.length;
      else return null;
    } else if (typeof current === "string" && key === "length") {
      current = current.length;
    } else if (current && typeof current === "object" && Object.prototype.hasOwnProperty.call(current, key as string)) {
      current = current[key as string];
    } else {
      return null;
    }
  }
  return current === undefined ? null : current;
}

export function binary(op: string, left: unknown, right: () => unknown): unknown {
  if (op === "&&") return truthy(left) ? right() : left;
  if (op === "||") return truthy(left) ? left : right();
  if (op === "??") return left ?? right();
  const value = right();
  if (op === "==") return left === value || (left == null && value == null);
  if (op === "!=") return !(left === value || (left == null && value == null));
  if (typeof left === "string" && typeof value === "string") {
    if (op === "+") return left + value;
    if (op === "<") return left < value;
    if (op === ">") return left > value;
    if (op === "<=") return left <= value;
    if (op === ">=") return left >= value;
  }
  if (typeof left !== "number" || typeof value !== "number") return null;
  switch (op) {
    case "+": return left + value;
    case "-": return left - value;
    case "*": return left * value;
    case "/": return value === 0 ? null : left / value;
    case "%": return value === 0 ? null : left % value;
    case "<": return left < value;
    case ">": return left > value;
    case "<=": return left <= value;
    case ">=": return left >= value;
  }
  return null;
}

export interface Insets {
  $: "Insets";
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export function insets(top: unknown, right: unknown, bottom: unknown, left: unknown): Insets {
  return { $: "Insets", top: num(top), right: num(right), bottom: num(bottom), left: num(left) };
}

/** A padding value as CSS: a number, Insets, or none. */
export function padding(value: unknown): string | undefined {
  if (typeof value === "number") return value + "px";
  if (value && typeof value === "object" && (value as Insets).$ === "Insets") {
    const v = value as Insets;
    return `${v.top}px ${v.right}px ${v.bottom}px ${v.left}px`;
  }
  return undefined;
}

export function border(width: unknown, color: unknown) {
  return { $: "Border", width: Math.max(0, num(width)), color: paint(color) ?? "var(--studio-border)" };
}

export function borderCss(value: unknown): string | undefined {
  if (!value || typeof value !== "object" || (value as Json).$ !== "Border") return undefined;
  const v = value as Json;
  return `${v.width}px solid ${v.color}`;
}

/** A colour: a theme variable (Color.primary) or a six-digit hex. */
export function paint(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  if (value.startsWith("var(--studio-") || /^#[0-9a-fA-F]{6}$/.test(value)) return value;
  return undefined;
}

export function gradient(style: string, stops: unknown[], begin: unknown, end: unknown): string {
  const colors = stops.map((stop) => paint(stop) ?? "transparent").join(", ");
  if (style === "radial") return `radial-gradient(circle, ${colors})`;
  if (style === "sweep") return `conic-gradient(${colors})`;
  // From begin towards end: CSS names the side it ends at.
  void begin;
  return `linear-gradient(${endDirection(typeof end === "string" ? end : "bottomCenter")}, ${colors})`;
}

function endDirection(anchor: string) {
  const map: Record<string, string> = {
    topLeft: "to top left", topCenter: "to top", top: "to top", topRight: "to top right",
    centerLeft: "to left", left: "to left", center: "to bottom", centerRight: "to right", right: "to right",
    bottomLeft: "to bottom left", bottomCenter: "to bottom", bottom: "to bottom", bottomRight: "to bottom right",
  };
  return map[anchor] ?? "to bottom";
}

export function responsive(bindings: Json, base: unknown, md: unknown, lg: unknown) {
  const w = width(bindings);
  if (w >= 1024) return lg !== undefined ? lg : md !== undefined ? md : base;
  if (w >= 768) return md !== undefined ? md : base;
  return base;
}

/** A Route token's path: this project's own page, or the storefront's usual one. */
export function route(name: string): string {
  return (
    settings.routePaths[name] ??
    ({
      home: "/", menu: "/", cart: "/cart", checkout: "/checkout", orders: "/orders", account: "/account",
      addresses: "/addresses", resetPassword: "/reset-password", tracking: "/orders/$orderId",
      location: "/select-location", stores: "/select-store",
    } as Record<string, string>)[name] ??
    name
  );
}

/** A record's page (Route.product …): its page, the id's param, the usual path. */
const recordRoutes: Record<string, [string, string, string]> = {
  "Route.product": ["product", "productId", "/product/$productId"],
  "Route.category": ["category", "categoryId", "/category/$categoryId"],
  "Route.order": ["tracking", "orderId", "/orders/$orderId"],
};

function routePath(value: unknown): string {
  if (value && typeof value === "object" && typeof (value as Json).$ === "string") {
    const v = value as Json;
    const [page, param, usual] = recordRoutes[v.$] ?? recordRoutes["Route.order"];
    // The project's own page for it (/stores/$storeId/products/$productId …),
    // the record's id in its param; any other param is filled by navigate.
    const pattern = settings.routePaths[page] ?? usual;
    return pattern.split("/").map((part) => (part === "$" + param ? encodeURIComponent(text(v.id)) : part)).join("/");
  }
  return route(text(value));
}

// ------------------------------------------------------------- dark mode

/** The mode ToggleDarkMode switched to (data-theme on <html>); null: Config's. */
let themeOver: "light" | "dark" | null = null;

/** Whether the page is dark: switched to, or Config's (its color-scheme). */
export function isDarkMode(): boolean {
  if (themeOver) return themeOver === "dark";
  if (typeof document === "undefined") return false;
  return getComputedStyle(document.documentElement).colorScheme === "dark";
}

function toggleDarkMode() {
  themeOver = isDarkMode() ? "light" : "dark";
  document.documentElement.dataset.theme = themeOver;
}

export function fn(bindings: Json, name: string, args: unknown[]): unknown {
  const [a, b, c] = args;
  switch (name) {
    case "currentRoute": return read(bindings, ["route", "path"]) ?? "/";
    case "isDarkMode": return isDarkMode();
    case "isCurrentRoute": {
      const target = routePath(a);
      const pattern = target.split("/").map((part) => (part.startsWith("$") ? "[^/]+" : part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))).join("/");
      return new RegExp("^" + pattern + "$").test(text(read(bindings, ["route", "path"]) ?? "/"));
    }
    case "upper": return a == null ? null : text(a).toUpperCase();
    case "lower": return a == null ? null : text(a).toLowerCase();
    case "truncate": return a == null ? null : text(a).slice(0, Math.max(0, Math.trunc(num(b))));
    case "length":
    case "count": return typeof a === "string" || Array.isArray(a) ? a.length : 0;
    case "join": return Array.isArray(a) ? a.map((v) => (v && typeof v === "object" ? "" : text(v))).join(text(b)) : "";
    case "contains": return typeof a === "string" ? a.includes(text(b)) : Array.isArray(a) && a.includes(b);
    case "isEmpty": return a == null || a === "" || (Array.isArray(a) && a.length === 0);
    case "min": return Math.min(num(a), num(b));
    case "max": return Math.max(num(a), num(b));
    case "round": return Math.floor(num(a) + 0.5);
    case "floor": return Math.floor(num(a));
    case "ceil": return Math.ceil(num(a));
    case "clamp": return Math.min(Math.max(num(a), num(b)), num(c));
    case "take": return Array.isArray(a) ? a.slice(0, Math.max(0, Math.trunc(num(b)))) : [];
    case "first": return Array.isArray(a) && a.length ? a[0] : null;
    case "ratio": {
      const parts = text(a).split(":").map(Number);
      return parts.length === 2 && parts[0] > 0 && parts[1] > 0 ? parts[0] / parts[1] : 1;
    }
    case "discountPercent":
      return num(b) > num(a) && num(b) > 0 ? Math.min(100, Math.max(0, Math.floor((1 - num(a) / num(b)) * 100 + 0.5))) : 0;
    case "formatMoney": {
      // The page's store's currency, else the storefront's (the cart's
      // store's, a listed store's): never a currency none of them use.
      const currency = read(bindings, ["store", "currency"]) ?? storefront.currency;
      return `${currency} ${(num(a) / 100).toFixed(2)}`;
    }
    case "filter":
      return Array.isArray(a) ? a.filter((item) => read(item, text(b).split(".")) === c).slice(0, 200) : [];
    case "search": {
      if (!Array.isArray(a)) return [];
      const words = text(b).toLowerCase().trim().split(/\s+/).filter(Boolean);
      const fields = Array.isArray(c) ? c : [];
      return a
        .filter((item) => {
          const haystack = fields
            .map((field) => read(item, text(field).split(".")))
            .map((value) => (Array.isArray(value) ? value.join(" ") : text(value)))
            .join(" ")
            .toLowerCase();
          return words.every((word) => haystack.includes(word));
        })
        .slice(0, 200);
    }
  }
  return null;
}

/** ForEach: each item's element, or the empty one. */
export function each(list: unknown, limit: unknown, build: (item: any, index: number) => ReactNode, empty: ReactNode): ReactNode[] {
  const items = Array.isArray(list) ? list.slice(0, Math.min(100, Math.max(0, Math.trunc(num(limit))))) : [];
  if (items.length === 0) return empty == null ? [] : [empty];
  return items.map(build);
}

/** A ForEach item's key: its id where it has one, so a list that changes keeps its items. */
export function key(prefix: string, item: unknown, index: number): string {
  const id = item && typeof item === "object" ? (item as Json).id : undefined;
  return prefix + ":" + (id != null ? "id:" + text(id) : "at:" + index);
}

export function scrollTo(id: string) {
  document.getElementById("studio-" + id)?.scrollIntoView({ behavior: "smooth", block: "start" });
}

/** Elements keyed by position where they have no key of their own. */
export function kids(children: unknown): ReactNode[] {
  if (!Array.isArray(children)) return children == null ? [] : [children as ReactNode];
  return children.map((child, index) =>
    child && typeof child === "object" && "key" in (child as ReactElement) && (child as ReactElement).key != null ? (
      child
    ) : (
      <Fragment key={"at:" + index}>{child as ReactNode}</Fragment>
    ),
  );
}

export function notice(message: string) {
  const id = ++noticeId;
  notices = [{ id, message }];
  noticeListeners.forEach((listener) => listener());
  // How long it shows: Config's notice (theme.css's --studio-notice-ms), else 3.5s.
  const ms = typeof document === "undefined" ? 0 : Number(getComputedStyle(document.documentElement).getPropertyValue("--studio-notice-ms"));
  setTimeout(() => {
    notices = notices.filter((item) => item.id !== id);
    noticeListeners.forEach((listener) => listener());
  }, ms > 0 ? ms : 3500);
}

function Notices() {
  const shown = useSyncExternalStore(
    (listener) => {
      noticeListeners.add(listener);
      return () => noticeListeners.delete(listener);
    },
    () => notices,
    () => noServerNotices,
  );
  return (
    <div className="studio-notices" role="status" aria-live="polite">
      {shown.map((item) => (
        <div key={item.id} className="studio-notice">
          {item.message}
        </div>
      ))}
    </div>
  );
}

export function registerForm(id: string, api: FormApi | null) {
  if (!id) return;
  if (api) forms.set(id, api);
  else forms.delete(id);
}

// --------------------------------------------------------------- the page

interface PageInfo {
  pageId: string;
  pattern: string;
  /** What the page's Data settings imported, by name. */
  data: Json;
}

/**
 * A page, with the route it was opened with and the data it imported.
 * Pages without a Scaffold scroll, padded, as in the preview.
 */
export function Page({ id, pattern, padded, data = NO_DATA, children }: { id: string; pattern: string; padded: boolean; data?: Json; children: ReactNode }) {
  const info = useMemo(() => ({ pageId: id, pattern, data }), [id, pattern, data]);
  return (
    <PageContext.Provider value={info}>
      {padded ? <div className="studio-padded">{children}</div> : <div className="studio-page">{children}</div>}
    </PageContext.Provider>
  );
}

function useViewport() {
  // The server's size first, the browser's after hydration: both render alike.
  const [size, setSize] = useState(SERVER_VIEWPORT);
  useEffect(() => {
    const update = () => setSize({ width: window.innerWidth, height: window.innerHeight });
    update();
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);
  return size;
}

export interface Studio {
  bindings: Json;
  navigate(route: unknown, values?: Json): void;
  notice(message: string): void;
  run(name: string, args: Json, event: Event, bindings: Json): void;
  form(id: string): FormApi | null;
}

/** What a compiled component reads: the bindings, and how to act. */
export function useStudio(): Studio {
  const version = useSyncExternalStore(storefront.subscribe, storefront.getVersion, storefront.getVersion);
  const page = useContext(PageContext);
  const params = useParams({ strict: false }) as Record<string, string>;
  const location = useLocation();
  const viewport = useViewport();
  const sf = storefront;
  routeParams = params;
  // The store a page's address names is the chosen store (its cart, its
  // header), whatever was chosen before.
  const addressStore = params.storeId;
  useEffect(() => {
    if (!addressStore || !sf.connected) return;
    if (sf.store?.id === addressStore || sf.store?.slug === addressStore) return;
    sf.selectStore(addressStore).catch(() => {});
  }, [addressStore, sf]);
  const productId = params.productId;
  const orderId = params.orderId;
  useEffect(() => {
    // An order opened by its address (a link, a reload): fetched and followed.
    if (orderId && sf.connected && sf.order?.id !== orderId && sf.order?.order_number !== orderId) {
      sf.openOrder(orderId).catch((failure) => notice(errorText(failure)));
    }
  }, [orderId, sf]);
  const bindings = useMemo(() => {
    let product: Json | null = null;
    if (productId) {
      product =
        sf.openProduct && String(sf.openProduct.id) === productId
          ? sf.openProduct
          : (sf.products.find((item) => String(item.id) === productId) ?? null);
    }
    const imported = importedBindings(page.data);
    // An imported product is the one the page's options are chosen for.
    if (imported.product && typeof imported.product === "object") product = imported.product;
    const out: Json = {
      ...sf.bindings(product),
      viewport,
      route: { pageId: page.pageId, pattern: page.pattern, path: location.pathname, params },
    };
    if (product) {
      out.product = product;
      out.selectedProductId = product.id;
      out.addonGroups = product.addon_groups ?? [];
    }
    // The page's own imports, by their names: over any built-in of the same
    // name. The storefront's own state stays under $storefront: a page's
    // Client import named cart or stores (reshaped, rt.useClient) must not
    // hide the cart or the store list it's read from (client()).
    return { ...out, ...imported, $storefront: out };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [version, page, location.pathname, viewport, productId, JSON.stringify(params)]);
  return useMemo(
    () => ({
      bindings,
      navigate,
      notice,
      run: runAction,
      form: (id: string) => forms.get(id) ?? null,
    }),
    [bindings],
  );
}

/**
 * Goes to a route: a page path, a Route token's, or a record's (Route.product …),
 * with its search params (Navigate(search: Search(city: …))) as ?city= in the address.
 */
/** The open page's route params (useStudio keeps them): what a path to fill can reuse. */
let routeParams: Record<string, string> = {};

/**
 * A page path with its $params filled: from `given`, the open page's params,
 * then what the storefront knows (its store, the open product, the order).
 * Null when one can't be filled (or a record's id is empty): going there
 * would open "/stores/$storeId" itself.
 */
function fillPath(path: string, given: Json = {}): string | null {
  const sf = storefront;
  const known: Json = {
    // The id: a store's routes take it everywhere (some only it, not the slug).
    storeId: sf.store?.id ?? sf.store?.slug ?? sf.pinnedStoreId,
    productId: sf.openProduct?.id,
    orderId: sf.order?.id,
    ...routeParams,
    ...given,
  };
  const [pathname, query] = [path.split("?")[0], path.includes("?") ? path.slice(path.indexOf("?")) : ""];
  let missing = false;
  const filled = pathname
    .split("/")
    .map((part, index, parts) => {
      if (!part.startsWith("$")) {
        // A record's route with no id: "/product/" or "/orders/".
        if (part === "" && index === parts.length - 1 && index > 1) missing = true;
        return part;
      }
      const value = known[part.slice(1)];
      if (value == null || text(value) === "") {
        missing = true;
        return part;
      }
      return encodeURIComponent(text(value));
    })
    .join("/");
  return missing ? null : filled + query;
}

export function navigate(target: unknown, search?: Json, params?: Json) {
  const filled = fillPath(routePath(target), params);
  if (filled == null) {
    // Not "/stores/$storeId": nowhere, and why.
    notice("That page needs something chosen first.");
    return;
  }
  let path = filled;
  const query = new URLSearchParams();
  for (const [name, value] of Object.entries(search ?? {})) if (value != null && value !== "") query.set(name, text(value));
  if (query.size) path += (path.includes("?") ? "&" : "?") + query.toString();
  window.dispatchEvent(new CustomEvent("studio:navigate"));
  router?.history.push(path);
}

/** The storefront's actions (PlaceOrder, ChooseStore …), as the apps run them. */
export function runAction(name: string, args: Json, event: Event, bindings: Json) {
  const sf = storefront;
  const values: Json = event?.values && typeof event.values === "object" ? event.values : (event ?? {});
  const fail = (failure: unknown) => notice(errorText(failure));
  const quantity = typeof args.quantity === "number" ? Math.min(99, Math.max(1, Math.trunc(args.quantity))) : 1;
  const open = (product: Json) => {
    sf.openProduct = product;
    navigate({ $: "Route.product", id: product.id });
  };
  const findStores = () => {
    if (sf.connected) sf.searchStores().catch(() => {});
    navigate(route("stores"));
  };
  switch (name) {
    case "OpenProduct":
      if (args.product && typeof args.product === "object") open(args.product);
      return;
    case "AddToCart": {
      const product = args.product;
      if (!product || typeof product !== "object") return;
      const add = (full: Json) => {
        const result = sf.add(full, quantity);
        if (result === "added") return notice("Added to cart.");
        if (result === "unavailable") return notice("This product is unavailable.");
        // An option to choose first: never added without it.
        notice("Pick at least one option.");
        open(full);
      };
      // A product from a list without its options (a store's products): the
      // whole product first, so one with options to choose isn't added bare.
      if (!("addon_groups" in product) && sf.connected && product.id != null) {
        sf.product(text(product.id)).then(
          (full) => add({ ...product, ...full }),
          () => notice("This product couldn't be added. Try again."),
        );
        return;
      }
      add(product);
      return;
    }
    case "AddConfiguredProduct": {
      const product = bindings.product;
      if (!product || typeof product !== "object") return notice("This product is unavailable.");
      const result = sf.addConfigured(product, quantity);
      if (result === "added") return navigate(route("cart"));
      if (result === "unavailable") return notice("This product is unavailable.");
      return notice("Pick at least one option.");
    }
    case "PlaceOrder":
    case "SubmitExampleOrder": {
      if (sf.lines.length === 0) return notice("Add something to your cart first.");
      if (!sf.connected) return notice("Connect this site to a store to place orders.");
      const fulfilment = args.fulfilment ?? values.fulfilment;
      if (fulfilment != null) sf.checkout.update({ fulfilment });
      const problem = sf.deliveryProblem;
      if (problem) return notice(problem);
      const changes: Json = {};
      const map: Record<string, string> = {
        name: "customer_name", phone: "customer_phone", email: "customer_email", address: "delivery_address_line1",
        instructions: "delivery_instructions", payment: "payment_method", notes: "notes", fulfilment: "fulfilment",
      };
      for (const [from, to] of Object.entries(map)) if (values[from] != null) changes[to] = values[from];
      if (args.fulfilment != null) changes.fulfilment = args.fulfilment;
      sf.checkout.update(changes);
      sf.placeOrder().then(
        (order) => {
          navigate({ $: "Route.order", id: order.id });
          if (sf.awaitingPayment(order)) sf.payOnline(order.id).catch(fail);
        },
        (failure) => {
          const fields = Object.values(sf.fieldErrors).join(" ");
          notice(fields || errorText(failure));
        },
      );
      return;
    }
    case "SetCheckout":
      sf.checkout.update({ [text(args.field)]: args.value });
      sf.notify();
      if (sf.connected) void sf.refreshQuote();
      return;
    case "ToggleDarkMode":
      toggleDarkMode();
      // What reads isDarkMode() draws again.
      sf.notify();
      return;
    case "ConfirmDeliveryPoint": {
      // The point given, or where the customer is, or the store.
      const at = (given: unknown, ...fallbacks: unknown[]) =>
        [given, ...fallbacks].find((value): value is number => typeof value === "number") ?? 0;
      sf.confirmDeliveryPoint(
        at(args.latitude, sf.location?.latitude, sf.store?.latitude, -26.2041),
        at(args.longitude, sf.location?.longitude, sf.store?.longitude, 28.0473),
      );
      if (sf.connected) void sf.refreshQuote();
      return;
    }
    case "SetTip":
      if (typeof args.percent === "number") sf.checkout.update({ tip_cents: Math.round((sf.cartTotal * Math.trunc(args.percent)) / 100) });
      else sf.checkout.update({ tip_cents: typeof args.cents === "number" ? args.cents : 0 });
      sf.notify();
      if (sf.connected) void sf.refreshQuote();
      return;
    case "PayOrder": {
      const orderId = args.order == null ? text(sf.order?.id) : id(args.order, "id");
      if (!orderId) return notice("Open an order to pay for it.");
      sf.payOnline(orderId).catch(fail);
      return;
    }
    case "CancelOrder":
      if (!sf.connected) return notice("Connect this site to a store to cancel orders.");
      sf.cancelOrder().then(() => notice("Order cancelled."), fail);
      return;
    case "SubmitReview": {
      if (!sf.connected) return notice("Connect this site to a store to send reviews.");
      const rating = (value: unknown) => (typeof value === "number" && value > 0 ? Math.round(value) : undefined);
      sf.submitReview({
        foodRating: rating(args.foodRating ?? values.food_rating),
        deliveryRating: rating(args.deliveryRating ?? values.delivery_rating),
        foodComment: text(args.foodComment ?? values.food_comment),
        deliveryComment: text(args.deliveryComment ?? values.delivery_comment),
      }).then(() => notice("Thanks for your review."), fail);
      return;
    }
    case "SavePreviewAddress": {
      if (!sf.connected) return notice("Connect this site to a store to save addresses.");
      const line = text(values.address).trim();
      if (!line) return notice("Enter an address first.");
      sf.saveAddress({ label: text(values.label).trim(), line1: line }).then(() => notice("Address saved."), fail);
      return;
    }
    case "SignIn":
    case "SignUp": {
      if (!sf.connected) return notice("Connect this site to a store to sign in.");
      const given = (key: string) => text(args[key] ?? values[key]).trim();
      void sf.authenticate(name === "SignUp", given("email"), text(args.password ?? values.password), given("name"));
      return;
    }
    case "SignOut":
    case "SignOutPreviewCustomer":
      sf.signOut();
      return;
    case "ResetPreviewPassword": {
      if (!sf.connected) return notice("Connect this site to a store to reset passwords.");
      const email = text(values.email ?? sf.user?.email).trim();
      if (!email.includes("@")) return notice("Enter your email address.");
      sf.requestPasswordReset(email).then(() => notice("If that email has an account, a reset link is on its way."), fail);
      return;
    }
    case "SearchPlaces":
      if (sf.connected) sf.searchPlaces(text(args.query)).catch(fail);
      return;
    case "ChoosePlace":
      if (!sf.connected) return notice("Connect this site to a store to search addresses.");
      sf.resolvePlace(id(args.place, "place_id")).then((point) => {
        sf.setLocation(point);
        findStores();
      }, fail);
      return;
    case "UseMyLocation":
      sf.locateDevice().then(findStores, () => {
        if (sf.connected) void sf.loadCities();
      });
      return;
    case "ChooseCity":
      if (!args.city || typeof args.city !== "object") return;
      sf.chooseCity(args.city);
      findStores();
      return;
    case "SearchStores":
      if (sf.connected) sf.searchStores(text(args.query)).catch(fail);
      return;
    case "ChooseStore": {
      if (!sf.connected) return notice("Connect this site to a store to open its menu.");
      const storeId = id(args.store, "id");
      // Pages fetching their own menu read the chosen store from the cookie: set first.
      if (storeId && !sf.loadsMenu) rememberStore(storeId);
      if (storeId)
        sf.selectStore(storeId, args.store && typeof args.store === "object" ? args.store : undefined).then(storeChosen, fail);
      // The menu's page by the store chosen ("/stores/$storeId" → its id).
      navigate(route("menu"), undefined, storeId ? { storeId, store: storeId, id: storeId } : undefined);
      return;
    }
    case "ToggleOption":
      sf.toggleOption(bindings.product, text(args.group), text(args.choice));
      return;
    case "ChangeCartLine":
      sf.changeLine(id(args.line, "id"), typeof args.by === "number" ? Math.trunc(args.by) : 1);
      return;
    case "RemoveCartLine":
      sf.removeLine(id(args.line, "id"));
      return;
    case "OpenOrder":
      navigate({ $: "Route.order", id: id(args.order, "id") });
      return;
    case "RemoveAddress":
      if (!sf.connected) return notice("Connect this site to a store to change addresses.");
      sf.deleteAddress(id(args.address, "id")).then(() => notice("Address removed."), fail);
      return;
  }
  notice(name + " is coming soon.");
}

/** Every page, and what the site does once it is open in the browser. */
export function AppRoot({ children }: { children: ReactNode }) {
  const location = useLocation();
  useEffect(() => {
    if (started) return;
    started = true;
    const sf = storefront;
    // After the first render, which matched the server's: the visitor's own cart.
    sf.restoreCart();
    if (!sf.connected) return;
    void sf.restore().then(() => {
      // Their orders, from earlier visits too: only for someone with a session.
      if (sf.api?.token) void sf.loadOrders();
    });
    const pinned = sf.pinnedStoreId ?? sf.savedStoreId;
    // A store remembered from before: its page data too (the server read it
    // from the cookie already, unless this visit is the first since).
    if (pinned) sf.selectStore(pinned).then(() => (visitorStore() ? undefined : storeChosen()), () => {});
    // The cities, unless the page offering them fetches its own.
    else if (!settings.pageResources?.includes("cities")) void sf.loadCities();
    if (settings.entryPath === route("stores")) sf.searchStores().catch(() => {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => {
    window.scrollTo(0, 0);
    // The store list, opened by its address: the stores load for it.
    const sf = storefront;
    if (sf.connected && location.pathname === route("stores") && sf.storesStatus === "idle") sf.searchStores().catch(() => {});
  }, [location.pathname]);
  return (
    <>
      {children}
      <Notices />
    </>
  );
}

export function NotFound() {
  return (
    <div className="studio-padded studio-not-found">
      <h1>Page not found</h1>
      <p>
        <a href="/">Go to the menu</a>
      </p>
    </div>
  );
}

export function PageError({ error }: { error: unknown }) {
  return (
    <div className="studio-padded studio-not-found">
      <h1>Something went wrong</h1>
      <p>{errorText(error)}</p>
      <p>
        <a href="/">Go to the menu</a>
      </p>
    </div>
  );
}

// ------------------------------------------------------------- page data

/**
 * A Data's parameters as its query is keyed and fetched with: each as text,
 * one with no value (no store chosen yet) left out.
 */
export function params(values: Record<string, unknown>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [name, value] of Object.entries(values)) if (value != null && value !== "") out[name] = text(value);
  return out;
}

/**
 * Who's signed in, as a key for their data's queries: it changes when they
 * sign in or out, so what's theirs is asked for again. Empty when nobody is.
 */
export function useSession(): string {
  return useSyncExternalStore(storefront.subscribe, () => storefront.api?.token ?? "", () => "");
}

/**
 * The signed-in customer's data (Tenant.me, .history, .order, .addresses),
 * from the browser with their session: its {params} filled in, the others
 * (query) in the address. Nothing (null) when nobody's signed in.
 */
export async function signedInRead(path: string, query: string[], params: Record<string, string>, select?: string): Promise<unknown> {
  const api = storefront.api;
  if (!api?.token) return null;
  const filled = path.replace(/\{(\w+)\}/g, (_, name: string) => encodeURIComponent(params[name] ?? ""));
  const answer = await api.request("GET", filled, {
    auth: true,
    query: Object.fromEntries(query.filter((name) => params[name]).map((name) => [name, params[name]])),
  });
  return select ? read(answer, select.split(".")) : answer;
}

/** The site's store: the one it's pinned to, or the one the visitor chose. */
export function siteStore(): string {
  return settings.storeId || visitorStore() || "";
}

/** A server Data the API says doesn't exist makes the page a 404. */
export function notFoundOn404(failure: unknown): never {
  if (/\b404\b/.test(String((failure as Error)?.message ?? ""))) throw notFound();
  throw failure;
}

/**
 * The page's data again, once the visitor has chosen a store: Data that
 * takes "the site's store" is fetched for it (a pinned site never changes).
 */
export function storeChosen() {
  if (!settings.storeId) void router?.invalidate();
}

// ------------------------------------------------------------------- head

interface Site {
  app_name?: string;
  title?: string;
  description?: string;
  keywords?: string;
  image_url?: string;
  image_alt?: string;
  site_name?: string;
  twitter_handle?: string;
  indexable?: boolean;
  follow?: boolean;
  locale?: string;
  google_verification?: string;
  bing_verification?: string;
  site_url?: string;
  theme_color?: string;
  /** The business's icon came with the build (public/icons, favicon.png). */
  has_icon?: boolean;
  business?: Record<string, any>;
}

export function siteLanguage(value: Site) {
  return (value.locale ?? "en").replace("_", "-");
}

/** JSON-LD for a <script>: "</" can't close it from inside a string. */
function jsonLd(value: Json) {
  return JSON.stringify(value).split("</").join("<\\/");
}

/** Every page's head: the business's website settings (Studio's Release, SEO). */
export function siteHead(value: Site, stylesheets: string[]) {
  site = value;
  const name = value.app_name ?? "";
  const title = value.title || name;
  const meta: Meta[] = [
    { charSet: "utf-8" },
    { name: "viewport", content: "width=device-width, initial-scale=1, viewport-fit=cover" },
    { title },
    { property: "og:type", content: "website" },
    { property: "og:site_name", content: value.site_name || name },
    { property: "og:title", content: title },
    { name: "twitter:card", content: https(value.image_url) ? "summary_large_image" : "summary" },
  ];
  if (value.theme_color) meta.push({ name: "theme-color", content: value.theme_color });
  if (value.description)
    meta.push({ name: "description", content: value.description }, { property: "og:description", content: value.description });
  if (https(value.image_url)) {
    meta.push({ property: "og:image", content: value.image_url! }, { name: "twitter:image", content: value.image_url! });
    if (value.image_alt) meta.push({ property: "og:image:alt", content: value.image_alt });
  }
  if (value.keywords) meta.push({ name: "keywords", content: value.keywords });
  if (value.locale) meta.push({ property: "og:locale", content: value.locale });
  if (value.twitter_handle) meta.push({ name: "twitter:site", content: value.twitter_handle });
  if (value.google_verification) meta.push({ name: "google-site-verification", content: value.google_verification });
  if (value.bing_verification) meta.push({ name: "msvalidate.01", content: value.bing_verification });
  if (value.indexable === false || value.follow === false)
    meta.push({
      name: "robots",
      content: `${value.indexable === false ? "noindex" : "index"}, ${value.follow === false ? "nofollow" : "follow"}`,
    });
  const links = [
    ...stylesheets.map((href) => ({ rel: "stylesheet", href })),
    { rel: "manifest", href: "/manifest.json" },
    // Only the business's own icon: linking ones that aren't there is a 404.
    ...(value.has_icon
      ? [
          { rel: "icon", href: "/favicon.png" },
          { rel: "apple-touch-icon", href: "/icons/Icon-192.png" },
        ]
      : []),
    { rel: "preconnect", href: "https://fonts.googleapis.com" },
    { rel: "preconnect", href: "https://fonts.gstatic.com", crossOrigin: "anonymous" as const },
    {
      rel: "stylesheet",
      href: "https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap",
    },
  ];
  // The business as structured data, for search's rich results.
  const business = value.business ?? {};
  const siteUrl = https(value.site_url).replace(/\/$/, "");
  const ld: Json = { "@context": "https://schema.org", "@type": business.type || "LocalBusiness", name: value.site_name || name };
  const fields: [string, unknown][] = [
    ["description", value.description],
    ["url", siteUrl && siteUrl + "/"],
    ["image", https(value.image_url)],
    ["telephone", business.phone],
    ["email", business.email],
    ["priceRange", business.price_range],
    ["servesCuisine", business.cuisine],
  ];
  for (const [key, field] of fields) if (field) ld[key] = field;
  const parts: [string, string][] = [
    ["streetAddress", "street"],
    ["addressLocality", "city"],
    ["addressRegion", "region"],
    ["postalCode", "postal_code"],
    ["addressCountry", "country"],
  ];
  const address = Object.fromEntries(parts.filter(([, from]) => business[from]).map(([to, from]) => [to, business[from]]));
  if (Object.keys(address).length) ld.address = { "@type": "PostalAddress", ...address };
  if (Array.isArray(business.same_as)) ld.sameAs = business.same_as.filter((url: unknown) => https(url));
  return { meta, links, scripts: [{ type: "application/ld+json", children: jsonLd(ld) }] };
}

interface PageSeo {
  title?: string;
  description?: string;
  image?: string;
  schema?: string;
  subject?: string;
  noindex?: boolean;
}

/**
 * A page's own head, from its SEO settings over its data: title,
 * description, sharing image, canonical address and, for a product or a
 * restaurant, schema.org structured data. What it leaves out is the site's.
 */
export function pageHead(pathname: string, seo: (b: Json) => PageSeo, data: Json | undefined) {
  // The page's data as the page reads it: an imported menu's store and products too.
  const b: Json = importedBindings(data);
  const fields = seo(b);
  const meta: Meta[] = [];
  const siteUrl = https(site.site_url).replace(/\/$/, "");
  const name = site.site_name || site.app_name || "";
  if (fields.title)
    meta.push({ title: fields.title }, { property: "og:title", content: fields.title }, { name: "twitter:title", content: fields.title });
  if (fields.description)
    meta.push(
      { name: "description", content: fields.description },
      { property: "og:description", content: fields.description },
      { name: "twitter:description", content: fields.description },
    );
  if (https(fields.image)) meta.push({ property: "og:image", content: fields.image! }, { name: "twitter:image", content: fields.image! });
    // Not for search engines (Seo(index: false)).
  if (fields.noindex) meta.push({ name: "robots", content: "noindex" });
const links = siteUrl ? [{ rel: "canonical", href: siteUrl + pathname }] : [];
  if (siteUrl) meta.push({ property: "og:url", content: siteUrl + pathname });
  const scripts: { type: string; children: string }[] = [];
  const subject: Json | undefined = fields.subject ? b[fields.subject] : undefined;
  if (fields.schema === "Product" && subject && typeof subject === "object") {
    scripts.push({
      type: "application/ld+json",
      children: jsonLd({
        "@context": "https://schema.org",
        "@type": "Product",
        name: subject.name,
        description: subject.description || undefined,
        image: https(subject.image_url) || undefined,
        url: siteUrl ? siteUrl + pathname : undefined,
        brand: name ? { "@type": "Brand", name } : undefined,
        offers: {
          "@type": "Offer",
          price: (num(subject.display_price_cents ?? subject.price_cents) / 100).toFixed(2),
          priceCurrency: text(subject.currency || b.store?.currency || "ZAR"),
          availability: subject.is_available === false ? "https://schema.org/OutOfStock" : "https://schema.org/InStock",
        },
      }),
    });
  }
  if (fields.schema === "Restaurant" && subject && typeof subject === "object") {
    const street = [subject.address_line1, subject.address_line2].filter(Boolean).join(", ");
    scripts.push({
      type: "application/ld+json",
      children: jsonLd({
        "@context": "https://schema.org",
        "@type": "Restaurant",
        name: subject.name,
        description: subject.description || undefined,
        image: https(subject.banner_url) || https(subject.logo_url) || undefined,
        telephone: subject.phone || undefined,
        servesCuisine: Array.isArray(subject.cuisines) && subject.cuisines.length ? subject.cuisines : undefined,
        url: siteUrl ? siteUrl + pathname : undefined,
        address: street
          ? {
              "@type": "PostalAddress",
              streetAddress: street,
              addressLocality: subject.city,
              addressRegion: subject.region,
              postalCode: subject.postal_code,
              addressCountry: subject.country,
            }
          : undefined,
        geo:
          typeof subject.latitude === "number"
            ? { "@type": "GeoCoordinates", latitude: subject.latitude, longitude: subject.longitude }
            : undefined,
        aggregateRating:
          num(subject.rating_count) > 0
            ? { "@type": "AggregateRating", ratingValue: subject.rating, ratingCount: subject.rating_count }
            : undefined,
      }),
    });
  }
  return { meta, links, scripts };
}

/**
 * What a page or component imports from the client (Client.cart(), …): the
 * storefront's own state, reshaped as Studio's CLIENT_RESOURCES name it
 * (clientData.ts in Studio). Read on every render, so it follows the cart.
 */
export function client(bindings: Json, resource: string): unknown {
  // The storefront's own state, under any page import of the same name.
  const state: Json = bindings?.$storefront && typeof bindings.$storefront === "object" ? bindings.$storefront : (bindings ?? {});
  const list = (key: string): Json[] => (Array.isArray(state[key]) ? state[key] : []);
  switch (resource) {
    case "cart": {
      const lines = list("cart");
      return {
        lines,
        count: lines.reduce((count, line) => count + (Number(line.quantity) || 0), 0),
        total_cents:
          typeof state.cartTotal === "number" ? state.cartTotal : lines.reduce((total, line) => total + (Number(line.line_total_cents) || 0), 0),
      };
    }
    case "store":
      return state.store ?? null;
    case "stores":
      return { results: list("stores"), loading: Boolean(state.storesLoading) };
    case "location": {
      const where = state.location && typeof state.location === "object" ? state.location : null;
      return {
        set: Boolean(where),
        label: where?.label ?? "",
        latitude: where?.latitude ?? null,
        longitude: where?.longitude ?? null,
        locating: Boolean(state.locating),
        error: state.locationError ?? null,
        places: list("places"),
        cities: list("cities"),
      };
    }
    case "checkout":
      // Read in the browser (a component's import too): the quote follows the cart.
      if (typeof window !== "undefined") queueMicrotask(() => storefront.keepQuote());
      return { ...(state.checkout ?? {}), quote: state.quote ?? null };
    case "session":
      return { signed_in: Boolean(state.signedIn), signing_in: Boolean(state.signingIn), error: state.authError ?? null };
    case "choices":
      return { ...(state.configuration ?? {}), groups: list("optionGroups") };
    case "review":
      return state.review ?? null;
  }
  return null;
}

/** A client import in a page's route, for the Data after it: followed as it changes. */
export function useClient(resource: string): unknown {
  const version = useSyncExternalStore(storefront.subscribe, storefront.getVersion, storefront.getVersion);
  useEffect(() => {
    // A page showing the checkout: its quote (charges, fees, the total) kept current.
    if (resource === "checkout") storefront.keepQuote();
  }, [resource, version]);
  useEffect(() => {
    // A page reading the store list (whatever its address): the stores load for it.
    const sf = storefront;
    if (resource === "stores" && sf.connected && sf.storesStatus === "idle") sf.searchStores().catch(() => {});
  }, [resource]);
  return client(storefront.bindings(null), resource);
}

export class ApiError extends Error {
  constructor(
    public status: number,
    public error: string,
    message: string,
    public fields?: Record<string, string>,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

export function errorText(failure: unknown): string {
  return failure instanceof ApiError ? failure.message : "Something went wrong. Try again.";
}

function stored(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function store(key: string, value: string | null) {
  try {
    if (value == null) localStorage.removeItem(key);
    else localStorage.setItem(key, value);
  } catch {
    // Kept for this visit only.
  }
}

// ------------------------------------------------------------------- the API

/** The tenant API, from the browser: CORS is open on it, and nothing here is secret. */
export class StorefrontApi {
  token: string | null = stored(TOKEN_KEY);
  constructor(public baseUrl: string) {}

  async request<T = any>(
    method: string,
    path: string,
    options: { body?: unknown; auth?: boolean; query?: Record<string, unknown> } = {},
  ): Promise<T> {
    const headers: Record<string, string> = { Accept: "application/json" };
    if (options.body !== undefined) headers["Content-Type"] = "application/json";
    if (options.auth && this.token) headers.Authorization = "Bearer " + this.token;
    const search = new URLSearchParams();
    for (const [key, value] of Object.entries(options.query ?? {})) {
      if (value == null || value === "") continue;
      if (Array.isArray(value)) value.forEach((item) => search.append(key, String(item)));
      else search.set(key, String(value));
    }
    const query = search.toString();
    let response: Response;
    try {
      response = await fetch(this.baseUrl.replace(/\/+$/, "") + "/api/v1" + path + (query ? "?" + query : ""), {
        method,
        headers,
        body: options.body === undefined ? undefined : JSON.stringify(options.body),
      });
    } catch {
      throw new ApiError(0, "offline", "Could not reach the store. Check your connection.");
    }
    if (response.status === 204) return undefined as T;
    const text = await response.text();
    let parsed: any = null;
    try {
      parsed = text ? JSON.parse(text) : null;
    } catch {
      throw new ApiError(response.status, "invalid_response", "The store sent an answer this site can't read.");
    }
    if (!response.ok) {
      throw new ApiError(
        response.status,
        parsed?.error ?? "unknown",
        parsed?.message ?? "Something went wrong.",
        parsed?.fields,
      );
    }
    return parsed as T;
  }

  segment(value: string) {
    return encodeURIComponent(value);
  }
}

// ----------------------------------------------------------------- options

export interface OptionChoice {
  id: string;
  label: string;
  priceCents: number;
  groups: OptionGroup[];
}

export interface OptionGroup {
  id: string;
  label: string;
  min: number;
  max: number;
  choices: OptionChoice[];
}

/** A product's groups from the tenant API's addon_groups (or the preview's shape). */
export function parseGroups(groups: unknown, depth = 0): OptionGroup[] {
  if (!Array.isArray(groups) || depth > 6) return [];
  const number = (value: unknown) => (typeof value === "number" ? Math.round(value) : 0);
  return groups
    .slice(0, 20)
    .filter((group): group is Json => !!group && typeof group === "object" && group.is_active !== false)
    .map((group) => ({
      id: textOf(group.id),
      label: textOf(group.label ?? group.name),
      min: "min" in group ? number(group.min) : Math.max(number(group.min_select), group.is_required === true ? 1 : 0),
      max: Math.max(1, number("max" in group ? group.max : group.max_select)),
      choices: ((group.choices ?? group.options ?? []) as unknown[])
        .slice(0, 40)
        .filter((choice): choice is Json => !!choice && typeof choice === "object" && (choice as Json).is_available !== false)
        .map((choice) => ({
          id: textOf(choice.id),
          label: textOf(choice.label ?? choice.name),
          priceCents: number(choice.price ?? choice.price_delta_cents),
          groups: parseGroups(
            choice.groups ?? (choice.child_group && typeof choice.child_group === "object" ? [choice.child_group] : null),
            depth + 1,
          ),
        })),
    }));
}

function findGroup(groups: OptionGroup[], id: string): OptionGroup | null {
  for (const group of groups) {
    if (group.id === id) return group;
    for (const choice of group.choices) {
      const nested = findGroup(choice.groups, id);
      if (nested) return nested;
    }
  }
  return null;
}

/** The groups as a page reads them (optionGroups): selected groups' own groups right after, a level deeper. */
function groupBindings(groups: OptionGroup[], selected: Record<string, string[]>, depth = 0): Json[] {
  const out: Json[] = [];
  for (const group of groups) {
    const ids = selected[group.id] ?? [];
    out.push({
      id: group.id,
      label: group.label,
      min: group.min,
      max: group.max,
      single: isSingle(group),
      required: isRequired(group),
      depth,
      selected_count: ids.length,
      choices: group.choices.map((choice) => ({
        id: choice.id,
        label: choice.label,
        price_cents: choice.priceCents,
        selected: ids.includes(choice.id),
        disabled: !ids.includes(choice.id) && !isSingle(group) && ids.length >= group.max,
      })),
    });
    for (const choice of group.choices) if (ids.includes(choice.id)) out.push(...groupBindings(choice.groups, selected, depth + 1));
  }
  return out;
}

interface Selection {
  valid: boolean;
  labels: string[];
  priceCents: number;
  selections: Json[];
}

function selectionOf(groups: OptionGroup[], selected: Record<string, string[]>): Selection {
  let valid = true,
    price = 0;
  const labels: string[] = [],
    selections: Json[] = [];
  for (const group of groups) {
    const ids = selected[group.id] ?? [];
    if (
      ids.length < group.min ||
      ids.length > group.max ||
      new Set(ids).size !== ids.length ||
      ids.some((id) => !group.choices.some((choice) => choice.id === id))
    )
      valid = false;
    for (const choice of group.choices.filter((choice) => ids.includes(choice.id))) {
      const nested = selectionOf(choice.groups, selected);
      valid = valid && nested.valid;
      price += choice.priceCents + nested.priceCents;
      labels.push(choice.label, ...nested.labels);
      selections.push({ addon_id: choice.id, quantity: 1, children: nested.selections });
    }
  }
  return { valid, labels, priceCents: price, selections };
}

// -------------------------------------------------------------------- cart

export interface CartLine {
  id: string;
  product: Json;
  quantity: number;
  unitCents: number;
  choices: string[];
  selections: Json[];
  notes: string | null;
  /** Why the server can't order it as it is now (sold out, an option gone). */
  problem?: string | null;
}

export class Checkout {
  fulfilment = "delivery";
  paymentMethod: string | null = null;
  tipCents = 0;
  notes: string | null = null;
  customerName = "";
  customerPhone = "";
  customerEmail: string | null = null;
  addressId: string | null = null;
  addressLine1: string | null = null;
  addressLine2: string | null = null;
  city: string | null = null;
  region: string | null = null;
  postalCode: string | null = null;
  latitude: number | null = null;
  longitude: number | null = null;
  deliveryInstructions: string | null = null;
  deliveryPresetId: string | null = null;
  pointConfirmed = false;

  get delivery() {
    return this.fulfilment === "delivery";
  }

  update(changes: Json) {
    const text = (value: unknown) => {
      const string = value == null ? "" : String(value).trim();
      return string === "" ? null : string;
    };
    const number = (value: unknown) => (typeof value === "number" ? value : null);
    for (const [key, value] of Object.entries(changes)) {
      switch (key) {
        case "fulfilment":
        case "fulfilment_type": {
          const next = value === "collection" ? "pickup" : String(value);
          if (FULFILMENTS.includes(next)) this.fulfilment = next;
          break;
        }
        case "payment_method": {
          const next = text(value);
          this.paymentMethod = next && PAYMENT_METHODS.includes(next) ? next : null;
          break;
        }
        case "tip_cents":
          this.tipCents = typeof value === "number" ? Math.min(100000000, Math.max(0, Math.round(value))) : 0;
          break;
        case "notes":
          this.notes = text(value);
          break;
        case "customer_name":
          this.customerName = text(value) ?? "";
          break;
        case "customer_phone":
          this.customerPhone = text(value) ?? "";
          break;
        case "customer_email":
          this.customerEmail = text(value);
          break;
        case "delivery_address_id":
          this.addressId = text(value);
          break;
        case "delivery_address_line1":
          this.addressLine1 = text(value);
          break;
        case "delivery_address_line2":
          this.addressLine2 = text(value);
          break;
        case "delivery_city":
          this.city = text(value);
          break;
        case "delivery_region":
          this.region = text(value);
          break;
        case "delivery_postal_code":
          this.postalCode = text(value);
          break;
        case "delivery_latitude":
          this.latitude = number(value);
          break;
        case "delivery_longitude":
          this.longitude = number(value);
          break;
        case "delivery_instructions":
          this.deliveryInstructions = text(value);
          break;
        case "delivery_preset_id":
          this.deliveryPresetId = text(value);
          break;
      }
    }
  }

  useLocation(location: Location | null) {
    if (!location) return;
    this.latitude ??= location.latitude;
    this.longitude ??= location.longitude;
    this.addressLine1 ??= location.label;
  }

  quoteBody(storeId: string, items: Json[]): Json {
    const body: Json = { store_id: storeId, fulfilment_type: this.fulfilment, tip_cents: this.tipCents, items };
    if (this.paymentMethod) body.payment_method = this.paymentMethod;
    if (this.delivery) {
      if (this.latitude != null && this.longitude != null) {
        body.delivery_latitude = this.latitude;
        body.delivery_longitude = this.longitude;
      }
      if (this.deliveryPresetId) body.delivery_preset_id = this.deliveryPresetId;
    }
    return body;
  }

  orderBody(storeId: string, items: Json[]): Json {
    const body: Json = {
      ...this.quoteBody(storeId, items),
      customer_name: this.customerName,
      customer_phone: this.customerPhone,
    };
    if (this.customerEmail) body.customer_email = this.customerEmail;
    if (this.notes) body.notes = this.notes;
    if (this.delivery) {
      if (this.addressId) body.delivery_address_id = this.addressId;
      else {
        if (this.addressLine1) body.delivery_address_line1 = this.addressLine1;
        if (this.addressLine2) body.delivery_address_line2 = this.addressLine2;
        if (this.city) body.delivery_city = this.city;
        if (this.region) body.delivery_region = this.region;
        if (this.postalCode) body.delivery_postal_code = this.postalCode;
      }
      if (this.deliveryInstructions) body.delivery_instructions = this.deliveryInstructions;
    }
    return body;
  }

  toJson(): Json {
    return {
      fulfilment: this.fulfilment,
      payment_method: this.paymentMethod,
      tip_cents: this.tipCents,
      notes: this.notes,
      customer_name: this.customerName,
      customer_phone: this.customerPhone,
      customer_email: this.customerEmail,
      delivery_address_id: this.addressId,
      delivery_address_line1: this.addressLine1,
      delivery_address_line2: this.addressLine2,
      delivery_instructions: this.deliveryInstructions,
      delivery_preset_id: this.deliveryPresetId,
      delivery_latitude: this.latitude,
      delivery_longitude: this.longitude,
      delivery_point_confirmed: this.pointConfirmed,
    };
  }

  resetForNextOrder() {
    this.tipCents = 0;
    this.notes = null;
    this.deliveryInstructions = null;
  }
}

// -------------------------------------------------------------- storefront

export interface Location {
  label: string;
  latitude: number;
  longitude: number;
}

export class Storefront {
  readonly api: StorefrontApi | null;
  readonly pinnedStoreId: string | null;
  /** Whether choosing a store loads its menu (and cuisines), or leaves that to the pages. */
  loadsMenu = true;
  private listeners = new Set<() => void>();
  /** Bumped on every change: what React re-renders by. */
  version = 0;

  location: Location | null = null;
  places: Json[] = [];
  cities: Json[] = [];
  locating = false;
  locationError: string | null = null;
  stores: Json[] = [];
  storesStatus: Status = "idle";
  store: Json | null = null;
  menu: Json | null = null;
  cuisines: Json | null = null;
  deliveryOptions: Json | null = null;

  lines: CartLine[] = [];
  cartStoreId: string | null = null;
  private nextLine = 0;
  checkout = new Checkout();
  quote: Json | null = null;
  fieldErrors: Record<string, string> = {};

  orders: Json[] = [];
  order: Json | null = null;
  review: Json | null = null;
  driverLocation: Location | null = null;
  addresses: Json[] = [];
  user: Json | null = null;
  signingIn = false;
  authError: string | null = null;

  /** The product a page has open, as OpenProduct carried it. */
  openProduct: Json | null = null;
  private optionsProductId: unknown = undefined;
  private optionSelections: Record<string, string[]> = {};

  private requests = { stores: 0, menu: 0, places: 0, quote: 0 };
  private following: AbortController | null = null;
  private guestStarting: Promise<string> | null = null;

  constructor(
    apiBaseUrl: string,
    pinnedStoreId: string,
    private queries: QueryClient,
  ) {
    this.api = apiBaseUrl ? new StorefrontApi(apiBaseUrl) : null;
    this.pinnedStoreId = pinnedStoreId || null;
  }

  get connected() {
    return this.api != null;
  }

  // --- change ---------------------------------------------------------------

  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  getVersion = () => this.version;

  notify() {
    this.version++;
    this.saveCart();
    for (const listener of this.listeners) listener();
  }

  private get _api() {
    if (!this.api) throw new Error("This site isn't connected to a store.");
    return this.api;
  }

  // --- session --------------------------------------------------------------

  get signedIn() {
    return !!this.api?.token && this.user?.is_anonymous === false;
  }

  /** A session token, starting a guest session if needed. */
  async ensure(): Promise<string> {
    const api = this._api;
    if (api.token) return api.token;
    this.guestStarting ??= api
      .request("POST", "/auth/guest")
      .then((session) => {
        this.setSession(session);
        return session.token as string;
      })
      .finally(() => (this.guestStarting = null));
    return this.guestStarting;
  }

  private setSession(session: Json | null) {
    const api = this._api;
    api.token = session?.token ?? null;
    this.user = session?.user ?? null;
    store(TOKEN_KEY, api.token);
    this.notify();
  }

  /** Picks up the session kept from before, and who it's for. */
  async restore() {
    const api = this.api;
    if (!api?.token || this.user) return;
    try {
      this.user = await api.request("GET", "/me", { auth: true });
      this.notify();
    } catch (failure) {
      if (failure instanceof ApiError && failure.status === 401) this.setSession(null);
    }
  }

  async authenticate(signUp: boolean, email: string, password: string, name: string) {
    if (this.signingIn) return;
    if (!email.includes("@")) return this.setAuth(false, "Enter your email address.");
    if (!password) return this.setAuth(false, "Enter your password.");
    if (signUp && password.length < 8) return this.setAuth(false, "Choose a password of 8 characters or more.");
    this.setAuth(true, null);
    try {
      const session = signUp
        ? await this._api.request("POST", "/auth/sign-up", {
            auth: true,
            body: { email, password, ...(name ? { display_name: name } : {}) },
          })
        : await this._api.request("POST", "/auth/sign-in", { body: { email, password } });
      this.setSession(session);
      this.setAuth(false, null);
      void this.loadOrders();
    } catch (failure) {
      this.setAuth(false, errorText(failure));
    }
  }

  private setAuth(working: boolean, error: string | null) {
    this.signingIn = working;
    this.authError = error;
    this.notify();
  }

  signOut() {
    this.setSession(null);
    this.orders = [];
    this.addresses = [];
    this.notify();
  }

  // --- location -------------------------------------------------------------

  async searchPlaces(input: string) {
    const request = ++this.requests.places;
    if (input.trim().length < 3) {
      this.places = [];
      return this.notify();
    }
    await this.ensure();
    const body = await this._api.request("GET", "/places/autocomplete", {
      auth: true,
      query: { input: input.trim(), latitude: this.location?.latitude, longitude: this.location?.longitude },
    });
    if (request !== this.requests.places) return;
    this.places = (Array.isArray(body?.data) ? body.data : []).map((place: Json) => ({
      ...place,
      label: place.secondary_text ? `${place.main_text}, ${place.secondary_text}` : place.main_text,
    }));
    this.notify();
  }

  async resolvePlace(placeId: string): Promise<Location> {
    await this.ensure();
    const body = await this._api.request("GET", "/places/details", { auth: true, query: { place_id: placeId } });
    if (typeof body?.latitude !== "number" || typeof body?.longitude !== "number")
      throw new ApiError(0, "invalid", "This address has no coordinates.");
    return { label: body.address || body.name || "", latitude: body.latitude, longitude: body.longitude };
  }

  setLocation(location: Location | null) {
    this.location = location;
    this.notify();
  }

  async loadCities() {
    try {
      const body = await this.queries.fetchQuery({
        queryKey: ["cities"],
        queryFn: () => this._api.request("GET", "/cities"),
        staleTime: 5 * 60_000,
      });
      this.cities = (Array.isArray(body?.data) ? body.data : []).map((city: Json) => ({ ...city, label: city.name }));
      this.notify();
    } catch {
      // No cities is the same as none to offer.
    }
  }

  chooseCity(city: Json) {
    this.setLocation({ label: textOf(city.name), latitude: Number(city.latitude) || 0, longitude: Number(city.longitude) || 0 });
  }

  /** The browser's location, named when the address can be looked up. */
  async locateDevice() {
    this.locating = true;
    this.locationError = null;
    this.notify();
    try {
      const position = await new Promise<GeolocationPosition>((resolve, reject) => {
        if (!("geolocation" in navigator)) return reject(new Error("unsupported"));
        navigator.geolocation.getCurrentPosition(resolve, reject, { enableHighAccuracy: true, timeout: 12_000 });
      });
      let point: Location = { label: "Your location", latitude: position.coords.latitude, longitude: position.coords.longitude };
      try {
        await this.ensure();
        const named = await this._api.request("GET", "/places/reverse", {
          auth: true,
          query: { latitude: point.latitude, longitude: point.longitude },
        });
        if (named?.label) point = { ...point, label: named.label };
      } catch {
        // Unnamed is still a place to find stores near.
      }
      this.setLocation(point);
      return point;
    } catch (failure) {
      const code = (failure as GeolocationPositionError)?.code;
      this.locationError =
        code === 1
          ? "Location access is off for this site. Search for your address instead."
          : code === 3
            ? "Finding your location took too long. Search for your address instead."
            : "This browser can't share its location. Search for your address instead.";
      throw failure;
    } finally {
      this.locating = false;
      this.notify();
    }
  }

  // --- stores ---------------------------------------------------------------

  async searchStores(query?: string) {
    const request = ++this.requests.stores;
    this.storesStatus = "loading";
    this.notify();
    try {
      const params = {
        q: query?.trim() || undefined,
        latitude: this.location?.latitude,
        longitude: this.location?.longitude,
        status: "active",
        limit: 30,
      };
      const page = await this.queries.fetchQuery({
        queryKey: ["stores", params],
        queryFn: () => this._api.request("GET", "/stores", { query: params }),
        staleTime: 60_000,
      });
      if (request === this.requests.stores) {
        this.stores = Array.isArray(page?.data) ? page.data : [];
        this.storesStatus = "ready";
      }
    } catch (failure) {
      if (request === this.requests.stores) {
        this.storesStatus = "error";
      }
      throw failure;
    } finally {
      if (request === this.requests.stores) this.notify();
    }
  }

  /** Opens a store: its menu (required), cuisines and delivery options (optional). */
  async selectStore(idOrSlug: string, card?: Json) {
    const current = this.store;
    if (!current || (current.id !== idOrSlug && current.slug !== idOrSlug)) {
      // Another store's menu can't show meanwhile; the tapped card stands in.
      this.menu = null;
      this.cuisines = null;
      this.deliveryOptions = null;
      this.store = card ?? null;
    }
    const request = ++this.requests.menu;
    this.notify();
    if (!this.loadsMenu) return this.selectStoreOnly(idOrSlug, request);
    try {
      const api = this._api;
      const menu = await this.queries.fetchQuery({
        queryKey: ["menu", idOrSlug],
        queryFn: () => api.request("GET", `/stores/${api.segment(idOrSlug)}/menu`),
        staleTime: 60_000,
      });
      if (!menu || !Array.isArray(menu.categories)) throw new ApiError(0, "invalid", "The menu response is invalid.");
      const optional = <T>(read: () => Promise<T>) =>
        Promise.race([read(), new Promise<null>((resolve) => setTimeout(() => resolve(null), 4000))]).catch(() => null);
      const [cuisines, deliveryOptions] = await Promise.all([
        optional(() =>
          this.queries.fetchQuery({ queryKey: ["cuisines"], queryFn: () => api.request("GET", "/cuisines"), staleTime: 300_000 }),
        ),
        optional(() => this.deliveryOptionsOf(textOf(menu.store.id))),
      ]);
      if (request !== this.requests.menu) return;
      this.menu = menu;
      this.store = menu.store;
      void this.loadCart(textOf(menu.store.id));
      this.cuisines = cuisines as Json | null;
      this.deliveryOptions = deliveryOptions as Json | null;
      if (!this.pinnedStoreId) {
        store(STORE_KEY, textOf(menu.store.id));
        rememberStore(textOf(menu.store.id));
      }
    } finally {
      if (request === this.requests.menu) this.notify();
    }
  }

  /** A store's delivery options, asked for once a minute however many pages want them. */
  private deliveryOptionsOf(storeId: string) {
    const api = this._api;
    return this.queries.fetchQuery({
      queryKey: ["delivery-options", storeId],
      queryFn: () => api.request("GET", `/stores/${api.segment(storeId)}/delivery-options`),
      staleTime: 60_000,
    });
  }

  /** A store without its menu (the pages fetch that): the store and its delivery options. */
  private async selectStoreOnly(idOrSlug: string, request: number) {
    try {
      const api = this._api;
      const chosen = await this.queries.fetchQuery({
        queryKey: ["store", idOrSlug],
        queryFn: () => api.request("GET", `/stores/${api.segment(idOrSlug)}`),
        staleTime: 60_000,
      });
      if (!chosen?.id) throw new ApiError(0, "invalid", "The store response is invalid.");
      const deliveryOptions = await Promise.race([
        this.deliveryOptionsOf(textOf(chosen.id)),
        new Promise<null>((resolve) => setTimeout(() => resolve(null), 4000)),
      ]).catch(() => null);
      if (request !== this.requests.menu) return;
      this.store = chosen;
      this.deliveryOptions = deliveryOptions as Json | null;
      void this.loadCart(textOf(chosen.id));
      if (!this.pinnedStoreId) {
        store(STORE_KEY, textOf(chosen.id));
        rememberStore(textOf(chosen.id));
      }
    } finally {
      if (request === this.requests.menu) this.notify();
    }
  }

  /** The store a returning visitor last ordered from. */
  get savedStoreId() {
    return stored(STORE_KEY);
  }

  get products(): Json[] {
    const menu = this.menu;
    if (!menu) return [];
    const all: Json[] = [
      ...(menu.categories as Json[]).flatMap((category) => (Array.isArray(category.products) ? category.products : [])),
      ...(Array.isArray(menu.uncategorised) ? menu.uncategorised : []),
    ];
    return all.filter((product) => product.is_available_online !== false);
  }

  // --- product options -------------------------------------------------------

  selectionsFor(product: unknown): Record<string, string[]> {
    return product && typeof product === "object" && (product as Json).id === this.optionsProductId ? this.optionSelections : {};
  }

  private choose(product: unknown, groupId: string, choiceIds: string[]) {
    const id = product && typeof product === "object" ? (product as Json).id : undefined;
    if (id !== this.optionsProductId) {
      this.optionSelections = {};
      this.optionsProductId = id;
    }
    this.optionSelections = { ...this.optionSelections, [groupId]: choiceIds };
    this.notify();
  }

  toggleOption(product: unknown, groupId: string, choiceId: string) {
    const group = findGroup(groupsOf(product), groupId);
    const choice = group?.choices.find((item) => item.id === choiceId);
    if (!group || !choice) return;
    const ids = this.selectionsFor(product)[group.id] ?? [];
    if (isSingle(group)) return this.choose(product, group.id, [choice.id]);
    if (ids.includes(choice.id)) return this.choose(product, group.id, ids.filter((id) => id !== choice.id));
    if (ids.length < group.max) this.choose(product, group.id, [...ids, choice.id]);
  }

  configuration(product: unknown) {
    return selectionOf(groupsOf(product), this.selectionsFor(product));
  }

  // --- cart -------------------------------------------------------------------
  //
  // **On the server, when the site has one** (the tenant API's
  // /stores/{store}/cart): the customer's session's cart at each store,
  // priced there, so a reload, another tab or another device shows the same
  // cart. Each change shows at once here, then the server's answer (its
  // prices, its line ids) replaces it. A site with no API keeps the cart in
  // this browser, as before.

  /** Something the server refused (a cart problem): the runtime shows it. */
  onProblem: (message: string) => void = () => {};

  /** False once the tenant API turned out to have no cart (not updated yet). */
  private cartOnServer = true;

  private get serverCart() {
    return this.connected && this.cartOnServer;
  }

  /** A tenant API without /cart (older than 0083): the cart stays in this browser. */
  private noServerCart(failure: unknown) {
    if (!(failure instanceof ApiError) || (failure.status !== 404 && failure.status !== 405) || failure.error === "not_found") return false;
    this.cartOnServer = false;
    this.saveCart();
    return true;
  }

  /** The server's cart, as the lines the pages read. */
  private applyCart(cart: Json | null) {
    if (!cart || !Array.isArray(cart.items)) return;
    this.cartStoreId = textOf(cart.store_id) || this.cartStoreId;
    if (typeof cart.currency === "string" && /^[A-Z]{3}$/.test(cart.currency)) this.savedCurrency = cart.currency;
    this.lines = (cart.items as Json[]).map((item) => ({
      id: textOf(item.id),
      product: { id: item.product_id, name: item.name, image_url: item.image_url },
      quantity: Number(item.quantity) || 1,
      unitCents: cents(item.unit_cents),
      choices: Array.isArray(item.choices) ? item.choices : [],
      selections: Array.isArray(item.selections) ? item.selections : [],
      notes: item.notes ?? null,
      problem: item.problem ?? null,
    }));
    this.notify();
  }

  private cartRequests = 0;

  /** A cart change sent to the server; its answer is the cart from then on. */
  private async sendCart(method: string, path: string, body?: Json) {
    const storeId = this.storeForCart;
    if (!this.serverCart || !storeId) return;
    const request = ++this.cartRequests;
    try {
      await this.ensure();
      const cart = await this._api.request(method, `/stores/${this._api.segment(storeId)}/cart${path}`, { auth: true, body });
      if (request === this.cartRequests) this.applyCart(cart);
    } catch (failure) {
      if (this.noServerCart(failure)) return;
      this.onProblem(failure instanceof Error ? failure.message : "The cart couldn't be updated.");
      // What the server has, whatever happened here.
      void this.loadCart(storeId);
    }
  }

  /** A store's cart from the server: the session's, once there is one. */
  /** The cart being asked for, so a second ask for the same store waits on it. */
  private cartLoading: { storeId: string; done: Promise<void> } | null = null;

  async loadCart(storeId: string) {
    if (!this.serverCart || !storeId || !this.api?.token) return;
    if (this.cartLoading?.storeId === storeId) return this.cartLoading.done;
    const done = this.fetchCart(storeId).finally(() => {
      if (this.cartLoading?.done === done) this.cartLoading = null;
    });
    this.cartLoading = { storeId, done };
    return done;
  }

  private async fetchCart(storeId: string) {
    if (this.cartStoreId && this.cartStoreId !== storeId) this.lines = [];
    this.cartStoreId = storeId;
    const request = ++this.cartRequests;
    try {
      const cart = await this._api.request("GET", `/stores/${this._api.segment(storeId)}/cart`, { auth: true });
      if (request === this.cartRequests) this.applyCart(cart);
    } catch (failure) {
      // The cart shows as it was; the next change asks again.
      this.noServerCart(failure);
    }
  }

  private addLine(product: Json, quantity: number, unitCents: number, choices: string[] = [], selections: Json[] = []) {
    const storeId = (this.store?.id as string | undefined) ?? (product.store_id as string | undefined) ?? null;
    if (storeId && this.cartStoreId && storeId !== this.cartStoreId) this.lines = [];
    this.cartStoreId = storeId ?? this.cartStoreId;
    // On the server too: its answer replaces this line.
    void this.sendCart("POST", "/items", {
      product_id: textOf(product.id),
      quantity: Math.min(99, Math.max(1, quantity)),
      selections,
    });
    this.lines = [
      ...this.lines,
      {
        id: "line-" + ++this.nextLine,
        product,
        quantity: Math.min(99, Math.max(1, quantity)),
        unitCents,
        choices,
        selections,
        notes: null,
      },
    ];
    this.notify();
  }

  /** One product, whole (its addon_groups too): a list's products may come without them. */
  async product(id: string): Promise<Json> {
    const answer = await this.queries.fetchQuery({
      queryKey: ["product", id],
      queryFn: () => this._api.request("GET", "/products/" + encodeURIComponent(id)),
      staleTime: 60_000,
    });
    return answer && typeof answer === "object" && answer.data && typeof answer.data === "object" && !Array.isArray(answer.data) ? answer.data : answer;
  }

  add(product: Json, quantity = 1): AddResult {
    if (product.is_available === false) return "unavailable";
    if (groupsOf(product).some(isRequired)) return "needsOptions";
    this.addLine(product, quantity, cents(product.display_price_cents));
    return "added";
  }

  addConfigured(product: Json, quantity = 1): AddResult {
    if (product.is_available === false) return "unavailable";
    const selection = this.configuration(product);
    if (!selection.valid) return "needsOptions";
    this.addLine(product, quantity, cents(product.display_price_cents) + selection.priceCents, selection.labels, selection.selections);
    return "added";
  }

  changeLine(id: string, delta: number) {
    const line = this.lines.find((item) => item.id === id);
    if (!line) return;
    const quantity = Math.min(99, line.quantity + delta);
    // A line still on its way to the server (line-…) is settled by its answer.
    if (!id.startsWith("line-"))
      void (quantity > 0
        ? this.sendCart("PATCH", "/items/" + encodeURIComponent(id), { quantity })
        : this.sendCart("DELETE", "/items/" + encodeURIComponent(id)));
    this.lines = this.lines
      .map((item) => (item.id === id ? { ...item, quantity } : item))
      .filter((item) => item.quantity > 0);
    this.notify();
  }

  removeLine(id: string) {
    if (!id.startsWith("line-")) void this.sendCart("DELETE", "/items/" + encodeURIComponent(id));
    this.lines = this.lines.filter((line) => line.id !== id);
    this.notify();
  }

  get cartCount() {
    return this.lines.reduce((sum, line) => sum + (line.problem ? 0 : line.quantity), 0);
  }

  get cartTotal() {
    return this.lines.reduce((sum, line) => sum + (line.problem ? 0 : line.unitCents * line.quantity), 0);
  }

  private orderItems() {
    // What can't be ordered now (a problem the server named) isn't sent.
    return this.lines.filter((line) => !line.problem).map((line) => ({
      product_id: textOf(line.product.id),
      quantity: line.quantity,
      selections: line.selections,
      ...(line.notes?.trim() ? { notes: line.notes.trim() } : {}),
    }));
  }

  private saveCart() {
    // Not before the saved cart is read back: an empty one would replace it.
    if (!this.cartRestored) return;
    // The server's cart is the cart: only which store's it is stays here.
    if (this.serverCart) {
      store(CART_KEY, JSON.stringify({ storeId: this.cartStoreId, lines: [], currency: this.currency }));
      return;
    }
    store(CART_KEY, JSON.stringify({ storeId: this.cartStoreId, lines: this.lines, next: this.nextLine, currency: this.currency }));
  }

  /** The currency of the store the cart is from, remembered with the cart. */
  private savedCurrency: string | null = null;

  /**
   * What prices are in: the open store's, the quote's, the cart's store's
   * (remembered from before), a listed store's; ZAR when nothing says.
   */
  get currency(): string {
    const named = (value: unknown) => (typeof value === "string" && /^[A-Z]{3}$/.test(value) ? value : null);
    return (
      named(this.store?.currency) ??
      named(this.quote?.currency) ??
      this.savedCurrency ??
      named(this.stores.find((item) => named(item?.currency))?.currency) ??
      "ZAR"
    );
  }

  private cartRestored = false;

  /**
   * The cart from an earlier visit, read once the page has hydrated (so the
   * first render matches the server's). The server re-prices every line.
   */
  restoreCart() {
    if (this.cartRestored) return;
    this.cartRestored = true;
    try {
      const saved = JSON.parse(stored(CART_KEY) ?? "null");
      if (this.serverCart) {
        // Which store's cart: the one saved, else the chosen store's.
        if (typeof saved?.currency === "string" && /^[A-Z]{3}$/.test(saved.currency)) this.savedCurrency = saved.currency;
        const storeId = (typeof saved?.storeId === "string" && saved.storeId) || this.pinnedStoreId || this.savedStoreId;
        if (storeId) void this.loadCart(storeId);
      } else if (saved && Array.isArray(saved.lines)) {
        this.lines = saved.lines;
        this.cartStoreId = saved.storeId ?? null;
        this.nextLine = Number(saved.next) || saved.lines.length;
        if (typeof saved.currency === "string" && /^[A-Z]{3}$/.test(saved.currency)) this.savedCurrency = saved.currency;
      }
    } catch {
      // A cart that can't be read is an empty one.
    }
    this.notify();
  }

  // --- checkout ---------------------------------------------------------------

  private get storeForCart() {
    return this.cartStoreId ?? (this.store?.id as string | undefined) ?? null;
  }

  /** The cart and choices the last quote was asked for. */
  private quotedFor = "";

  /**
   * The quote kept current while a page shows the checkout: asked for again
   * whenever the cart or a checkout choice changes, so the charges a store
   * adds (and its delivery fee) show before the order is placed, never after.
   */
  keepQuote() {
    const storeId = this.storeForCart;
    if (!this.connected || !storeId || this.lines.length === 0) return;
    if (this.checkout.delivery) this.checkout.useLocation(this.location);
    const key = JSON.stringify(this.checkout.quoteBody(storeId, this.orderItems()));
    if (key !== this.quotedFor) void this.refreshQuote();
  }

  async refreshQuote() {
    const storeId = this.storeForCart;
    if (!storeId || this.lines.length === 0) {
      this.quote = null;
      return this.notify();
    }
    const request = ++this.requests.quote;
    if (this.checkout.delivery) this.checkout.useLocation(this.location);
    // What this quote is for (keepQuote asks again only when it changes).
    this.quotedFor = JSON.stringify(this.checkout.quoteBody(storeId, this.orderItems()));
    this.notify();
    try {
      await this.ensure();
      const quote = await this._api.request("POST", "/orders/quote", {
        auth: true,
        body: this.checkout.quoteBody(storeId, this.orderItems()),
      });
      if (request === this.requests.quote) {
        this.quote = quote;
      }
    } catch {
      // The checkout keeps the last quote; placing the order prices it anyway.
    } finally {
      if (request === this.requests.quote) this.notify();
    }
  }

  async placeOrder(): Promise<Json> {
    const storeId = this.storeForCart;
    if (!storeId || this.lines.length === 0) throw new Error("There is nothing in the cart to order.");
    this.fieldErrors = {};
    this.notify();
    try {
      await this.ensure();
      if (this.checkout.delivery) this.checkout.useLocation(this.location);
      const placed = await this._api.request("POST", "/orders", {
        auth: true,
        body: this.checkout.orderBody(storeId, this.orderItems()),
      });
      this.lines = [];
      this.checkout.resetForNextOrder();
      this.quote = null;
      this.order = placed;
      this.review = null;
      this.orders = [placed, ...this.orders.filter((item) => item.id !== placed.id)];
      void this.followOrder(placed.id);
      return placed;
    } catch (failure) {
      if (failure instanceof ApiError) this.fieldErrors = failure.fields ?? {};
      throw failure;
    } finally {
      this.notify();
    }
  }

  get deliveryFeeCents() {
    const presetId = this.checkout.deliveryPresetId;
    if (presetId) {
      const preset = ((this.deliveryOptions?.presets as Json[]) ?? []).find((item) => String(item.id) === presetId);
      if (preset) return cents(preset.fee_cents);
    }
    if (this.quote && this.checkout.delivery) return cents(this.quote.delivery_fee_cents);
    return cents(this.store?.delivery_fee_cents);
  }

  get deliveryProblem(): string | null {
    if (!this.checkout.delivery) return null;
    if (this.deliveryOptions?.mode === "preset")
      return this.checkout.deliveryPresetId ? null : "Choose where we should deliver.";
    return this.checkout.pointConfirmed ? null : "Confirm your delivery location on the map.";
  }

  confirmDeliveryPoint(latitude: number, longitude: number) {
    this.checkout.latitude = latitude;
    this.checkout.longitude = longitude;
    this.checkout.pointConfirmed = true;
    this.checkout.fulfilment = "delivery";
    this.notify();
  }

  // --- orders -----------------------------------------------------------------

  async loadOrders() {
    if (!this.connected) return;
    this.notify();
    try {
      await this.ensure();
      const page = await this._api.request("GET", "/orders", { auth: true });
      this.orders = Array.isArray(page?.data) ? page.data : [];
    } catch {
      // No orders to show is the same as none yet.
    } finally {
      this.notify();
    }
  }

  async openOrder(idOrNumber: string) {
    await this.ensure();
    const api = this._api;
    const next = await api.request("GET", `/orders/${api.segment(idOrNumber)}`, { auth: true });
    if (this.order?.id !== next.id) {
      this.review = null;
      this.driverLocation = null;
    }
    this.order = next;
    if (next.status === "delivered") {
      try {
        this.review = await api.request("GET", `/orders/${api.segment(next.id)}/review`, { auth: true });
      } catch {
        this.review = null;
      }
    }
    this.notify();
    if (!["delivered", "cancelled", "failed"].includes(next.status)) void this.followOrder(next.id);
    return next;
  }

  /** Follows an order live (server-sent events, read as a stream for the bearer token). */
  async followOrder(orderId: string) {
    this.following?.abort();
    const controller = new AbortController();
    this.following = controller;
    if (!this.connected) return;
    try {
      const token = await this.ensure();
      const api = this._api;
      const response = await fetch(api.baseUrl.replace(/\/+$/, "") + `/api/v1/orders/${api.segment(orderId)}/events`, {
        headers: { Accept: "text/event-stream", Authorization: "Bearer " + token },
        signal: controller.signal,
      });
      if (!response.ok || !response.body) return;
      const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
      let buffer = "";
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += value;
        let end: number;
        while ((end = buffer.indexOf("\n\n")) >= 0) {
          const block = buffer.slice(0, end);
          buffer = buffer.slice(end + 2);
          let type = "message",
            data = "";
          for (const line of block.split("\n")) {
            if (line.startsWith("event:")) type = line.slice(6).trim();
            else if (line.startsWith("data:")) data += line.slice(5).trim();
          }
          try {
            this.onOrderEvent(orderId, type, data ? JSON.parse(data) : {});
          } catch {
            // One unreadable event isn't the end of the stream.
          }
        }
      }
    } catch {
      // Live updates stop; the order is still there to reopen.
    }
  }

  private onOrderEvent(orderId: string, type: string, event: Json) {
    if (type === "status" && event.status) {
      if (this.order?.id === orderId) this.order = { ...this.order, status: event.status };
      this.orders = this.orders.map((item) => (item.id === orderId ? { ...item, status: event.status } : item));
      if (event.status === "delivered" || event.status === "cancelled") this.driverLocation = null;
    } else if (type === "driver_location" && this.order?.id === orderId && typeof event.latitude === "number") {
      this.driverLocation = { label: textOf(this.order?.driver_name) || "Driver", latitude: event.latitude, longitude: event.longitude };
    }
    this.notify();
  }

  awaitingPayment(order: Json | null = this.order) {
    return !!order && order.payment_method === "online" && order.payment_status !== "paid" &&
      order.status !== "cancelled" && order.status !== "failed";
  }

  /** Where to pay for an online order: the business's provider, in this tab. */
  async payOnline(orderId: string) {
    await this.ensure();
    const api = this._api;
    const body = await api.request("POST", `/orders/${api.segment(orderId)}/payfast`, { auth: true });
    if (typeof body?.url !== "string") throw new ApiError(0, "invalid", "The store didn't say where to pay.");
    window.location.assign(body.url);
  }

  async cancelOrder(orderId = this.order?.id as string | undefined) {
    if (!orderId) throw new Error("No order is open.");
    await this.ensure();
    const api = this._api;
    const cancelled = await api.request("POST", `/orders/${api.segment(orderId)}/cancel`, { auth: true });
    if (this.order?.id === orderId) this.order = cancelled;
    this.orders = this.orders.map((item) => (item.id === orderId ? cancelled : item));
    this.notify();
  }

  async submitReview(review: { foodRating?: number; deliveryRating?: number; foodComment?: string; deliveryComment?: string }) {
    const current = this.order;
    if (!current) throw new Error("No order is open.");
    const delivery = current.fulfilment_type === "delivery";
    await this.ensure();
    const api = this._api;
    const body: Json = {};
    if (review.foodRating) body.food_rating = review.foodRating;
    if (review.foodComment?.trim()) body.food_comment = review.foodComment.trim();
    if (delivery && review.deliveryRating) body.delivery_rating = review.deliveryRating;
    if (delivery && review.deliveryComment?.trim()) body.delivery_comment = review.deliveryComment.trim();
    this.review = await api.request("POST", `/orders/${api.segment(current.id)}/review`, { auth: true, body });
    this.notify();
  }

  // --- account ----------------------------------------------------------------

  async loadAddresses() {
    await this.ensure();
    const page = await this._api.request("GET", "/addresses", { auth: true });
    this.addresses = Array.isArray(page?.data) ? page.data : [];
    this.notify();
  }

  async saveAddress(body: Json) {
    await this.ensure();
    await this._api.request("POST", "/addresses", { auth: true, body });
    await this.loadAddresses();
  }

  async deleteAddress(id: string) {
    await this.ensure();
    const api = this._api;
    await api.request("DELETE", `/addresses/${api.segment(id)}`, { auth: true });
    if (this.checkout.addressId === id) this.checkout.update({ delivery_address_id: null });
    await this.loadAddresses();
  }

  async requestPasswordReset(email: string) {
    await this._api.request("POST", "/auth/password/forgot", { body: { email } });
  }

  // --- bindings ---------------------------------------------------------------

  /** What pages read, by the same names as the Studio preview and the apps. */
  bindings(product: unknown): Json {
    const selection = this.configuration(product);
    const categories = this.menu ? (this.menu.categories as Json[]) : null;
    const presets = (this.deliveryOptions?.presets as Json[] | undefined) ?? null;
    const out: Json = {
      places: this.places,
      cities: this.cities,
      locating: this.locating,
      locationError: this.locationError,
      storesLoading: this.storesStatus === "loading",
      optionGroups: groupBindings(groupsOf(product), this.selectionsFor(product)),
      deliveryFeeCents: this.deliveryFeeCents,
      cart: this.lines.map((line) => ({
        id: line.id,
        product: line.product,
        product_id: textOf(line.product.id),
        name: textOf(line.product.name),
        quantity: line.quantity,
        unit_cents: line.unitCents,
        line_total_cents: line.unitCents * line.quantity,
        choices: line.choices,
        notes: line.notes,
      })),
      cartCount: this.cartCount,
      cartTotal: this.cartTotal,
      configuration: { valid: selection.valid, addon_price_cents: selection.priceCents },
      checkout: this.checkout.toJson(),
      orders: this.orders,
      signedIn: this.signedIn,
      signingIn: this.signingIn,
      authError: this.authError,
    };
    if (this.location) out.location = this.location;
    if (this.stores.length) out.stores = this.stores;
    if (this.store) out.store = this.store;
    if (this.menu && categories) {
      out.menu = this.menu;
      out.categories = categories;
      out.category = categories[0] ?? null;
      out.products = this.products;
    }
    if (this.cuisines) {
      out.cuisinesPage = this.cuisines;
      out.cuisines = this.cuisines.data ?? [];
    }
    if (this.deliveryOptions) {
      out.deliveryOptions = this.deliveryOptions;
      out.deliveryPresets = presets;
      out.deliveryPreset = presets?.[0] ?? null;
    }
    if (this.quote) out.quote = this.quote;
    if (Object.keys(this.fieldErrors).length) out.checkoutErrors = this.fieldErrors;
    if (this.order) {
      out.order = this.order;
      out.orderItems = this.order.items ?? [];
    }
    if (this.review) out.review = this.review;
    if (this.driverLocation) out.driverLocation = this.driverLocation;
    if (this.addresses.length) out.addresses = this.addresses;
    if (this.user) out.me = this.user;
    return out;
  }
}

export const visitorStore = createIsomorphicFn()
  .server((): string => getCookie(STORE_COOKIE) ?? "")
  .client((): string => {
    try {
      const match = document.cookie.match(/(?:^|;\s*)upskale_store=([^;]*)/);
      return match ? decodeURIComponent(match[1]) : "";
    } catch {
      return "";
    }
  });

/** Remembers the visitor's store for the server too: a year, this site only. */
export function rememberStore(id: string) {
  try {
    document.cookie = `${STORE_COOKIE}=${encodeURIComponent(id)}; path=/; max-age=31536000; samesite=lax`;
  } catch {
    // Kept in the browser's storage still.
  }
}

const mainAlign: Record<string, string> = {
  start: "flex-start", center: "center", end: "flex-end", between: "space-between", around: "space-around",
  evenly: "space-evenly", spaceBetween: "space-between", spaceAround: "space-around", spaceEvenly: "space-evenly",
};

// An Anchor as [justify-content, align-items] in a row.
const anchors: Record<string, [string, string]> = {
  topLeft: ["flex-start", "flex-start"], topCenter: ["center", "flex-start"], top: ["center", "flex-start"],
  topRight: ["flex-end", "flex-start"], centerLeft: ["flex-start", "center"], left: ["flex-start", "center"],
  center: ["center", "center"], centerRight: ["flex-end", "center"], right: ["flex-end", "center"],
  bottomLeft: ["flex-start", "flex-end"], bottomCenter: ["center", "flex-end"], bottom: ["center", "flex-end"],
  bottomRight: ["flex-end", "flex-end"],
};

const shadows: Record<string, string> = {
  sm: "0 1px 3px rgba(0,0,0,0.14)",
  md: "0 4px 14px rgba(0,0,0,0.14)",
  lg: "0 10px 30px rgba(0,0,0,0.14)",
};

const textShadows: Record<string, string> = {
  sm: "0 0.5px 1.5px rgba(0,0,0,0.25)",
  md: "0 2px 7px rgba(0,0,0,0.25)",
  lg: "0 5px 15px rgba(0,0,0,0.25)",
};

// ------------------------------------------------------------------ layout

export function Scaffold(p: P) {
  return (
    <div className="studio-scaffold" style={{ backgroundColor: rt.paint(p.background) }}>
      {p.appBar != null && <header className="studio-scaffold-header">{p.appBar}</header>}
      <main className="studio-scaffold-body">{p.body}</main>
      {p.bottomNavigationBar != null && (
        <nav className="studio-scaffold-bottom" aria-label="Navigation">
          {p.bottomNavigationBar}
        </nav>
      )}
    </div>
  );
}

export function ScrollView(p: P) {
  const horizontal = p.direction === "horizontal";
  return (
    <div
      className={"studio-scroll" + (horizontal ? " is-horizontal" : "")}
      role="region"
      aria-label={p.label != null ? rt.text(p.label) : undefined}
      style={{ padding: rt.padding(p.padding) }}
    >
      <div className="studio-scroll-content">{p.child}</div>
    </div>
  );
}

function FlexBox(p: P & { axis: "horizontal" | "vertical"; kind: "Column" | "Row" | "Flex" }) {
  const vertical = p.axis === "vertical";
  const cross = p.crossAxisAlignment ?? p.align ?? (p.kind === "Flex" ? "center" : "stretch");
  const main = p.mainAxisAlignment ?? p.justify;
  const size = p.mainAxisSize ?? (p.kind === "Column" ? "min" : "max");
  const style: CSSProperties = {
    flexDirection: vertical ? "column" : "row",
    gap: has(p.gap) ? px(p.gap) : undefined,
    padding: rt.padding(p.padding),
    alignItems: crossAlign[cross] ?? "stretch",
    justifyContent: main ? mainAlign[main] : undefined,
    flexWrap: p.wrap ? "wrap" : undefined,
    width: !vertical && size === "min" ? "max-content" : undefined,
    height: vertical && size === "max" ? "100%" : undefined,
  };
  return (
    <div className={"studio-flex" + (vertical ? " is-vertical" : " is-horizontal")} style={style}>
      {rt.kids(p.children)}
    </div>
  );
}

export function Expanded(p: P) {
  return (
    <div className="studio-expanded" style={{ flex: `${Math.max(1, Math.trunc(n(p.flex) || 1))} 1 0px` }}>
      {p.child}
    </div>
  );
}

export function Flexible(p: P) {
  const flex = Math.max(1, Math.trunc(n(p.flex) || 1));
  return (
    <div className="studio-expanded" style={{ flex: p.fit === "tight" ? `${flex} 1 0px` : `0 ${flex} auto` }}>
      {p.child}
    </div>
  );
}

export function Spacer(p: P) {
  return (
    <div
      aria-hidden="true"
      style={{
        flex: has(p.flex) || !has(p.size) ? `${Math.max(1, Math.trunc(n(p.flex) || 1))} 1 0px` : undefined,
        width: px(p.size),
        height: px(p.size),
        flexShrink: 0,
      }}
    />
  );
}

export function Divider(p: P) {
  return <hr className="studio-divider" style={{ borderTop: `${Math.max(1, n(p.thickness) || 1)}px solid ${rt.paint(p.color) ?? "var(--studio-border)"}` }} />;
}

export function Wrap(p: P) {
  const vertical = p.direction === "vertical";
  const spacing = px(p.spacing) ?? 0,
    run = px(p.runSpacing) ?? 0;
  return (
    <div
      className="studio-wrap"
      style={{
        flexDirection: vertical ? "column" : "row",
        rowGap: vertical ? spacing : run,
        columnGap: vertical ? run : spacing,
        padding: rt.padding(p.padding),
        justifyContent: mainAlign[p.alignment] ?? "flex-start",
        alignContent: mainAlign[p.runAlignment] ?? "flex-start",
        alignItems: crossAlign[p.crossAxisAlignment] ?? "flex-start",
      }}
    >
      {rt.kids(p.children)}
    </div>
  );
}

export function Grid(p: P) {
  const cols = has(p.cols) ? Math.min(100, Math.max(1, Math.trunc(n(p.cols)))) : 0;
  return (
    <div
      className="studio-grid"
      style={{
        gap: px(p.gap),
        padding: rt.padding(p.padding),
        gridTemplateColumns: cols
          ? `repeat(${cols}, minmax(0, 1fr))`
          : `repeat(auto-fill, minmax(min(100%, ${Math.max(40, n(p.minItemWidth) || 180)}px), 1fr))`,
      }}
    >
      {rt.kids(p.children)}
    </div>
  );
}

export function SizedBox(p: P) {
  return (
    <div className="studio-sized" style={{ width: px(p.width), height: px(p.height), flexShrink: has(p.width) || has(p.height) ? 0 : undefined }}>
      {p.child}
    </div>
  );
}

export function Stack(p: P) {
  const anchor: string = p.alignment || "topLeft";
  const fit = p.fit || "loose";
  const [justify, align] = anchors[anchor] ?? anchors.topLeft;
  return (
    <StackContext.Provider value={anchor}>
      <div
        className="studio-stack"
        style={{
          width: has(p.width) ? px(p.width) : fit === "expand" ? "100%" : undefined,
          height: has(p.height) ? px(p.height) : fit === "expand" ? "100%" : undefined,
          overflow: rt.truthy(p.clip) ? "hidden" : "visible",
          justifyItems: fit === "expand" ? "stretch" : justify === "flex-start" ? "start" : justify === "flex-end" ? "end" : "center",
          alignItems: fit === "expand" ? "stretch" : align === "flex-start" ? "start" : align === "flex-end" ? "end" : "center",
        }}
      >
        {rt.kids(p.children)}
      </div>
    </StackContext.Provider>
  );
}

export function Positioned(p: P) {
  const anchor = useContext(StackContext);
  const style: CSSProperties = { position: "absolute" };
  for (const name of ["top", "right", "bottom", "left", "width", "height"] as const) {
    if (typeof p[name] === "number") (style as any)[name] = p[name];
  }
  if (p.left == null && p.right == null) {
    if (anchor.includes("Right") || anchor === "right") style.right = 0;
    else if (anchor.includes("Left") || anchor === "left") style.left = 0;
    else {
      style.left = "50%";
      style.transform = "translateX(-50%)";
    }
  }
  if (p.top == null && p.bottom == null) {
    if (anchor.startsWith("bottom")) style.bottom = 0;
    else if (anchor.startsWith("top")) style.top = 0;
    else {
      style.top = "50%";
      style.transform = (style.transform ?? "") + " translateY(-50%)";
    }
  }
  return (
    <div className="studio-positioned" style={style}>
      {p.child}
    </div>
  );
}

export function Layers(p: P) {
  return (
    <div className="studio-layers">
      {p.child}
      {rt.kids(p.layers)}
    </div>
  );
}

export function Layer(p: P) {
  const anchor: string = p.anchor || "center";
  const style: CSSProperties = { position: "absolute", padding: px(p.inset) };
  if (anchor.includes("Left") || anchor === "left") style.left = 0;
  if (anchor.includes("Right") || anchor === "right") style.right = 0;
  if (anchor.startsWith("top")) style.top = 0;
  if (anchor.startsWith("bottom")) style.bottom = 0;
  if (["top", "bottom", "center", "topCenter", "bottomCenter"].includes(anchor)) {
    style.left = "50%";
    style.transform = "translateX(-50%)";
  }
  if (["left", "right", "center", "centerLeft", "centerRight"].includes(anchor)) {
    style.top = "50%";
    style.transform = (style.transform ?? "") + " translateY(-50%)";
  }
  return <div style={style}>{p.child}</div>;
}

export function Box(p: P) {
  const placed = has(p.alignment) ? anchors[String(p.alignment)] : undefined;
  const circle = p.shape === "circle";
  const transform = [has(p.rotate) && `rotate(${n(p.rotate)}deg)`, has(p.scale) && `scale(${n(p.scale)})`].filter(Boolean).join(" ");
  const style: CSSProperties = {
    padding: rt.padding(p.padding),
    margin: rt.padding(p.margin),
    backgroundColor: rt.paint(p.background),
    backgroundImage: typeof p.gradient === "string" ? p.gradient : undefined,
    ...(placed && { display: "flex", justifyContent: placed[0], alignItems: placed[1] }),
    transform: transform || undefined,
    opacity: has(p.opacity) ? Math.max(0, Math.min(1, n(p.opacity))) : undefined,
    borderRadius: circle ? "50%" : has(p.radius) ? px(p.radius) : undefined,
    border: rt.borderCss(p.border),
    width: px(p.width),
    height: px(p.height),
    minWidth: px(p.minWidth),
    minHeight: px(p.minHeight),
    maxWidth: px(p.maxWidth),
    maxHeight: px(p.maxHeight),
    aspectRatio: has(p.aspectRatio) && n(p.aspectRatio) > 0 ? String(n(p.aspectRatio)) : undefined,
    overflow: rt.truthy(p.clip) || circle ? "hidden" : undefined,
    boxShadow: shadows[p.shadow],
    flexShrink: has(p.width) || has(p.height) ? 0 : undefined,
  };
  const id = has(p.id) ? "studio-" + rt.text(p.id) : undefined;
  if (p.onTap) {
    return (
      <button
        type="button"
        id={id}
        className="studio-box studio-tap"
        aria-label={has(p.ariaLabel) ? rt.text(p.ariaLabel) : undefined}
        style={style}
        onClick={(event) => {
          // The innermost tap is the one meant, as in the app.
          event.stopPropagation();
          p.onTap({});
        }}
      >
        {p.child}
      </button>
    );
  }
  return (
    <div id={id} className="studio-box" role={has(p.ariaLabel) ? "group" : undefined} aria-label={has(p.ariaLabel) ? rt.text(p.ariaLabel) : undefined} style={style}>
      {p.child}
    </div>
  );
}

export function Animate(p: P) {
  const curves: Record<string, string> = {
    linear: "linear", ease: "ease", easeIn: "cubic-bezier(0.42, 0, 1, 1)", easeOut: "cubic-bezier(0, 0, 0.58, 1)",
    easeInOut: "cubic-bezier(0.42, 0, 0.58, 1)", easeOutBack: "cubic-bezier(0.175, 0.885, 0.32, 1.275)",
  };
  const effect: string = p.effect || "fade";
  const distance = has(p.distance) ? n(p.distance) : 24;
  const from: Record<string, [number, number, number]> = {
    fade: [0, 0, 1], slideUp: [0, distance, 1], slideDown: [0, -distance, 1], slideLeft: [distance, 0, 1],
    slideRight: [-distance, 0, 1], scale: [0, 0, 0.9], pop: [0, 0, 0.6],
  };
  const [dx, dy, scale] = from[effect] ?? from.fade;
  return (
    <div
      className="studio-animate"
      style={
        {
          "--studio-animate-x": dx + "px",
          "--studio-animate-y": dy + "px",
          "--studio-animate-scale": scale,
          animationDuration: (has(p.duration) ? n(p.duration) : 400) + "ms",
          animationDelay: n(p.delay) + "ms",
          animationTimingFunction: curves[p.curve] ?? curves.easeOut,
        } as CSSProperties
      }
    >
      {p.child}
    </div>
  );
}

// ----------------------------------------------------------------- content

export function Text(p: P) {
  const content = p.child;
  if (content == null || content === "") return null;
  const decoration =
    p.decoration != null
      ? ({ none: "none", underline: "underline", overline: "overline", lineThrough: "line-through" } as Record<string, string>)[p.decoration]
      : rt.truthy(p.strike)
        ? "line-through"
        : undefined;
  const align = ({ start: "left", center: "center", end: "right", left: "left", right: "right", justify: "justify" } as Record<string, any>)[p.align];
  const noWrap = has(p.softWrap) && !rt.truthy(p.softWrap);
  const style: CSSProperties = {
    fontSize: has(p.size) ? n(p.size) : undefined,
    fontWeight: has(p.weight) ? n(p.weight) : undefined,
    fontStyle: p.fontStyle === "italic" ? "italic" : undefined,
    color: rt.paint(p.color),
    backgroundColor: rt.paint(p.background),
    textAlign: align,
    textDecorationLine: decoration,
    textDecorationColor: rt.paint(p.decorationColor),
    textDecorationStyle: p.decorationStyle,
    textDecorationThickness: has(p.decorationThickness) ? n(p.decorationThickness) : undefined,
    letterSpacing: has(p.letterSpacing) ? n(p.letterSpacing) : undefined,
    wordSpacing: has(p.wordSpacing) ? n(p.wordSpacing) : undefined,
    lineHeight: has(p.lineHeight) ? Math.max(0.5, n(p.lineHeight) || 1.5) : undefined,
    fontFamily: has(p.fontFamily) ? `${rt.text(p.fontFamily)}, var(--studio-font)` : undefined,
    textShadow: textShadows[p.shadow],
    direction: p.textDirection,
    whiteSpace: noWrap ? "pre" : undefined,
    overflow: p.overflow && p.overflow !== "visible" ? "hidden" : undefined,
    textOverflow: p.overflow === "ellipsis" ? "ellipsis" : undefined,
  };
  if (has(p.maxLines)) {
    style.display = "-webkit-box";
    style.WebkitLineClamp = Math.max(1, Math.trunc(n(p.maxLines)));
    style.WebkitBoxOrient = "vertical";
    style.overflow = "hidden";
  }
  const label = has(p.semanticsLabel) ? rt.text(p.semanticsLabel) : undefined;
  const body = rt.text(content);
  const level = has(p.level) ? Math.min(6, Math.max(1, Math.trunc(n(p.level)))) : p.role === "heading" ? 2 : 0;
  if (level) {
    const Heading = ("h" + level) as "h1";
    return (
      <Heading className="studio-text" style={style} aria-label={label}>
        {body}
      </Heading>
    );
  }
  return (
    <p className="studio-text" style={style} aria-label={label}>
      {body}
    </p>
  );
}

/** A picture's address: a web address, or one on the tenant API. */
function imageSource(value: unknown): string | undefined {
  if (typeof value !== "string" || !value) return undefined;
  if (/^https?:\/\//.test(value)) return value;
  // One of the site's own files (public/uploads/x.png at /uploads/x.png);
  // never //host, which is another site's.
  if (/^\/(?!\/)/.test(value)) return value;
  return undefined;
}

export function Image(p: P) {
  const src = imageSource(p.src);
  const [failed, setFailed] = useState(false);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    setFailed(false);
    setLoaded(false);
  }, [src]);
  const ratio = has(p.aspectRatio) && n(p.aspectRatio) > 0 ? n(p.aspectRatio) : undefined;
  const style: CSSProperties = {
    width: has(p.width) ? px(p.width) : "100%",
    height: px(p.height),
    aspectRatio: ratio ? String(ratio) : undefined,
    borderRadius: px(p.radius),
  };
  const alt = rt.truthy(p.decorative) ? "" : rt.text(p.alt);
  if (!src || failed) {
    if (p.fallback === "none") return null;
    return (
      <div className="studio-image is-missing" role={alt ? "img" : "presentation"} aria-label={alt || undefined} style={style}>
        {p.fallback === "initials" && alt ? <span className="studio-initials">{alt.trim().slice(0, 2).toUpperCase()}</span> : <MdImage aria-hidden="true" />}
      </div>
    );
  }
  return (
    <img
      className={"studio-image" + (loaded ? " is-loaded" : "")}
      src={src}
      alt={alt}
      loading="lazy"
      decoding="async"
      referrerPolicy="no-referrer"
      onLoad={() => setLoaded(true)}
      onError={() => setFailed(true)}
      style={{ ...style, objectFit: p.fit === "contain" ? "contain" : p.fit === "fill" ? "fill" : "cover" }}
    />
  );
}

export function Icon(p: P) {
  const Glyph = p.name as IconType | undefined;
  if (typeof Glyph !== "function") return null;
  return (
    <Glyph
      className="studio-icon"
      aria-hidden="true"
      style={{ fontSize: has(p.size) ? n(p.size) : "var(--studio-icon-size)", color: rt.paint(p.color), flexShrink: 0 }}
    />
  );
}

export function Badge(p: P) {
  const tone = ["primary", "success", "warning", "danger"].includes(p.tone) ? p.tone : "textMuted";
  return (
    <span className="studio-badge" style={{ "--studio-tone": `var(--studio-${tone})` } as CSSProperties}>
      {rt.text(p.label)}
    </span>
  );
}

function ButtonBase(p: P & { kind: string; onPress?: () => void }) {
  const Glyph = typeof p.icon === "function" ? (p.icon as IconType) : null;
  const label = rt.text(p.label);
  const small = typeof p.size === "number" && p.size < 20;
  const style = p.style || (p.kind === "TriggerButton" ? "ghost" : "primary");
  return (
    <button
      type="button"
      className={`studio-button is-${style}` + (small ? " is-small" : "") + (!label && Glyph ? " is-icon" : "")}
      disabled={rt.truthy(p.disabled)}
      aria-label={has(p.ariaLabel) ? rt.text(p.ariaLabel) : undefined}
      style={{ width: rt.truthy(p.fullWidth) ? "100%" : undefined }}
      onClick={(event) => {
        event.stopPropagation();
        p.onPress?.();
      }}
    >
      {Glyph && <Glyph aria-hidden="true" />}
      {label && <span>{label}</span>}
    </button>
  );
}

export function SubmitButton(p: P) {
  const form = useContext(rt.FormContext);
  return <ButtonBase {...p} kind="SubmitButton" onPress={() => form?.submit()} />;
}

export function ResetButton(p: P) {
  const form = useContext(rt.FormContext);
  return <ButtonBase {...p} kind="ResetButton" style={p.style || "secondary"} onPress={() => form?.reset()} />;
}

export function TriggerButton(p: P) {
  const open = useContext(DrawerContext);
  return <ButtonBase {...p} kind="TriggerButton" onPress={() => open?.()} />;
}

export function Unavailable(p: P) {
  return (
    <div className="studio-unavailable">
      <strong>{rt.text(p.title ?? p.label ?? p.name)}</strong>
      <span>Coming soon.</span>
    </div>
  );
}

export function Form(p: P) {
  const registry = useMemo(() => ({ fields: new Set<Field>(), values: {} as Record<string, unknown> }), []);
  const api = useMemo<rt.FormApi>(
    () => ({
      submit() {
        let valid = true;
        for (const field of registry.fields) if (!field.validate()) valid = false;
        if (valid) p.onSubmit?.({ values: { ...registry.values } });
      },
      reset() {
        for (const field of registry.fields) field.reset();
        p.onReset?.({ values: { ...registry.values } });
      },
    }),
    // The handlers are read when it's used, not when it's made.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [registry, p.onSubmit, p.onReset],
  );
  useEffect(() => {
    const id = rt.text(p.id);
    rt.registerForm(id, api);
    return () => rt.registerForm(id, null);
  }, [api, p.id]);
  return (
    <FieldsContext.Provider value={registry}>
      <rt.FormContext.Provider value={api}>
        <form
          className="studio-form"
          noValidate
          onSubmit={(event) => {
            event.preventDefault();
            api.submit();
          }}
        >
          {p.child}
        </form>
      </rt.FormContext.Provider>
    </FieldsContext.Provider>
  );
}

/** The preview's field rules and messages (formRuntime's validateField). */
function validate(value: unknown, p: P, label: string): string | null {
  const empty = value == null || (typeof value === "string" && value.trim() === "");
  if (rt.truthy(p.required) && (empty || value === false)) return label + " is required.";
  if (empty) return null;
  if (p.type === "number" && (typeof value !== "number" || !Number.isFinite(value))) return "Enter a number for " + label + ".";
  if (typeof value === "number") {
    if (has(p.min) && value < n(p.min)) return `${label} must be at least ${n(p.min)}.`;
    if (has(p.max) && value > n(p.max)) return `${label} must be at most ${n(p.max)}.`;
  }
  if (typeof value === "string") {
    if (has(p.minLength) && value.length < n(p.minLength)) return `${label} needs at least ${n(p.minLength)} characters.`;
    if (has(p.maxLength) && value.length > n(p.maxLength)) return `${label} allows at most ${n(p.maxLength)} characters.`;
    if (p.type === "email" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return "Enter a valid email address.";
    if (p.type === "url" && !/^https?:\/\/\S+$/.test(value)) return "Enter a valid URL.";
  }
  return null;
}

/** A field's value, its error, and its place in the form around it. */
function useField(p: P, initial: unknown) {
  const registry = useContext(FieldsContext);
  const bound = has(p.stateValue);
  const [own, setOwn] = useState<unknown>(() => (bound ? p.stateValue : initial));
  const value = bound ? p.stateValue : own;
  const [error, setError] = useState<string | null>(null);
  const name = rt.text(p.name ?? p.state);
  const label = rt.text(p.label) || name || "This field";
  const latest = useRef({ value, initial, p });
  latest.current = { value, initial, p };
  const set = (next: unknown) => {
    if (bound) p.setStateValue?.(next);
    else setOwn(next);
  };
  useEffect(() => {
    if (registry && name) registry.values[name] = value;
  });
  useEffect(() => {
    if (!registry) return;
    const field: Field = {
      validate() {
        const { value, p } = latest.current;
        const message = rt.truthy(p.disabled) ? null : validate(value, p, label);
        setError(message);
        return message == null;
      },
      reset() {
        set(latest.current.initial);
        setError(null);
      },
    };
    registry.fields.add(field);
    return () => {
      registry.fields.delete(field);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [registry, label]);
  return { value, set, error, setError, name, label };
}

function fieldStyle(p: P): CSSProperties {
  return {
    background: rt.paint(p.background),
    color: rt.paint(p.color),
    border: rt.borderCss(p.border),
    borderRadius: has(p.radius) ? px(p.radius) : undefined,
    padding: rt.padding(p.padding),
    fontSize: has(p.fontSize) ? n(p.fontSize) : undefined,
    ...(p.placeholderColor ? ({ "--studio-placeholder": rt.paint(p.placeholderColor) } as CSSProperties) : {}),
    ...(p.focusColor ? ({ "--studio-focus": rt.paint(p.focusColor) } as CSSProperties) : {}),
  };
}

function Labelled(p: P & { id: string; error: string | null; children: ReactNode }) {
  return (
    <div className="studio-field">
      {has(p.label) && rt.text(p.label) && (
        <label htmlFor={p.id} style={{ color: rt.paint(p.labelColor) }}>
          {rt.text(p.label)}
        </label>
      )}
      {p.children}
      {p.error ? (
        <small className="studio-field-error" role="alert">
          {p.error}
        </small>
      ) : (
        has(p.helperText) && (
          <small className="studio-field-helper" style={{ color: rt.paint(p.helperColor) }}>
            {rt.text(p.helperText)}
          </small>
        )
      )}
    </div>
  );
}

function TextInput(p: P & { search?: boolean }) {
  const id = useId();
  const field = useField(p, p.value ?? "");
  const type = p.search ? "search" : (p.type as string) || "text";
  const changed = (raw: string) => {
    const next = type === "number" ? (raw === "" ? null : Number(raw)) : raw;
    field.set(next);
    if (field.error) field.setError(null);
    p.onChanged?.({ value: next, input: { value: next, name: field.name } });
  };
  const common = {
    id,
    name: field.name || undefined,
    value: field.value == null ? "" : String(field.value),
    placeholder: has(p.placeholder) ? rt.text(p.placeholder) : undefined,
    disabled: rt.truthy(p.disabled),
    "aria-label": has(p.ariaLabel) ? rt.text(p.ariaLabel) : undefined,
    "aria-invalid": field.error ? true : undefined,
    maxLength: has(p.maxLength) ? Math.trunc(n(p.maxLength)) : undefined,
    style: fieldStyle(p),
    className: "studio-input",
  };
  return (
    <Labelled {...p} id={id} error={field.error}>
      {n(p.rows) > 1 ? (
        <textarea {...common} rows={Math.trunc(n(p.rows))} onChange={(event) => changed(event.target.value)} />
      ) : (
        <input
          {...common}
          type={type === "search" ? "search" : type}
          inputMode={type === "number" ? "decimal" : undefined}
          onChange={(event) => changed(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter" && p.onSubmitted) {
              event.preventDefault();
              p.onSubmitted({ value: field.value, input: { value: field.value, name: field.name } });
            }
          }}
        />
      )}
    </Labelled>
  );
}

export function Checkbox(p: P) {
  const id = useId();
  const field = useField(p, rt.truthy(p.value));
  return (
    <div className="studio-field">
      <label className="studio-checkbox" htmlFor={id} style={{ color: rt.paint(p.labelColor) }}>
        <input
          id={id}
          type="checkbox"
          name={field.name || undefined}
          checked={rt.truthy(field.value)}
          disabled={rt.truthy(p.disabled)}
          onChange={(event) => {
            field.set(event.target.checked);
            if (field.error) field.setError(null);
            p.onChanged?.({ value: event.target.checked, input: { value: event.target.checked, checked: event.target.checked, name: field.name } });
          }}
        />
        <span>{rt.text(p.label)}</span>
      </label>
      {field.error ? <small className="studio-field-error">{field.error}</small> : has(p.helperText) && <small className="studio-field-helper">{rt.text(p.helperText)}</small>}
    </div>
  );
}

function optionsOf(options: unknown): P[] {
  const out: P[] = [];
  const walk = (value: unknown) => {
    if (Array.isArray(value)) value.forEach(walk);
    else if (isValidElement(value)) {
      const props = (value as ReactElement<P>).props;
      if (props && "value" in props) out.push(props);
      else if (props?.children) walk(props.children);
    }
  };
  walk(options);
  return out;
}

export function SelectField(p: P) {
  const id = useId();
  const choices = optionsOf(p.options);
  const values = choices.map((option) => rt.text(option.value));
  const first = values.includes(rt.text(p.value)) ? rt.text(p.value) : (values[0] ?? "");
  const field = useField(p, first);
  return (
    <Labelled {...p} id={id} error={field.error}>
      <select
        id={id}
        className="studio-input studio-select"
        name={field.name || undefined}
        value={field.value == null ? "" : String(field.value)}
        disabled={rt.truthy(p.disabled)}
        aria-label={has(p.ariaLabel) ? rt.text(p.ariaLabel) : undefined}
        style={fieldStyle(p)}
        onChange={(event) => {
          field.set(event.target.value);
          if (field.error) field.setError(null);
          p.onChanged?.({ value: event.target.value, input: { value: event.target.value, name: field.name } });
        }}
      >
        {has(p.placeholder) && (
          <option value="" disabled>
            {rt.text(p.placeholder)}
          </option>
        )}
        {choices.map((option, index) => (
          <option key={index} value={rt.text(option.value)} disabled={rt.truthy(option.disabled)}>
            {rt.text(option.label ?? option.value)}
          </option>
        ))}
      </select>
    </Labelled>
  );
}

/** Read by its SelectField; never drawn on its own. */
export function SelectOption(_: P) {
  return null;
}

// ---------------------------------------------------------------- behaviour

export function Drawer(p: P) {
  const [opened, setOpened] = useState(false);
  const controlled = has(p.open);
  const shown = controlled ? rt.truthy(p.open) : opened;
  const close = () => {
    if (controlled) p.onClose?.({});
    else setOpened(false);
  };
  useEffect(() => {
    // Going somewhere from inside closes it.
    const onNavigate = () => (controlled ? undefined : setOpened(false));
    window.addEventListener("studio:navigate", onNavigate);
    return () => window.removeEventListener("studio:navigate", onNavigate);
  }, [controlled]);
  useEffect(() => {
    if (!shown) return;
    const onKey = (event: KeyboardEvent) => event.key === "Escape" && close();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });
  const side = ["left", "right", "bottom"].includes(p.side) ? p.side : "left";
  return (
    <DrawerContext.Provider value={() => setOpened(true)}>
      {p.trigger}
      {shown &&
        createPortal(
          <div className="studio-drawer-layer">
            <button type="button" className="studio-drawer-scrim" aria-label="Close" onClick={close} />
            <div
              className={"studio-drawer is-" + side}
              role="dialog"
              aria-modal="true"
              style={{ width: side === "bottom" ? undefined : has(p.width) ? Math.min(480, Math.max(240, n(p.width))) : 300 }}
            >
              {p.child}
            </div>
          </div>,
          document.body,
        )}
    </DrawerContext.Provider>
  );
}

export function Carousel(p: P) {
  const track = useRef<HTMLDivElement>(null);
  const items = rt.kids(p.children);
  const [index, setIndex] = useState(0);
  const go = (next: number) => {
    const el = track.current;
    const target = el?.children[Math.max(0, Math.min(items.length - 1, next))] as HTMLElement | undefined;
    target?.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "start" });
  };
  return (
    <div className="studio-carousel">
      <div
        ref={track}
        className={"studio-carousel-track" + (p.snap === false ? "" : " is-snap")}
        style={{ gap: px(p.gap) ?? 12 }}
        onScroll={(event) => {
          const el = event.currentTarget;
          const width = (el.firstElementChild as HTMLElement | null)?.offsetWidth || el.clientWidth || 1;
          setIndex(Math.round(el.scrollLeft / (width + (px(p.gap) ?? 12))));
        }}
      >
        {items.map((item, i) => (
          <div key={i} className="studio-carousel-item" style={{ width: has(p.itemWidth) ? px(p.itemWidth) : "85%" }}>
            {item}
          </div>
        ))}
      </div>
      {(rt.truthy(p.showDots) || rt.truthy(p.showArrows)) && (
        <div className="studio-carousel-controls">
          {rt.truthy(p.showArrows) && (
            <button type="button" aria-label="Previous" disabled={index <= 0} onClick={() => go(index - 1)}>
              ‹
            </button>
          )}
          {rt.truthy(p.showDots) && (
            <span className="studio-carousel-dots">
              {items.map((_, i) => (
                <button key={i} type="button" aria-label={`Slide ${i + 1}`} aria-current={i === index} onClick={() => go(i)} />
              ))}
            </span>
          )}
          {rt.truthy(p.showArrows) && (
            <button type="button" aria-label="Next" disabled={index >= items.length - 1} onClick={() => go(index + 1)}>
              ›
            </button>
          )}
        </div>
      )}
    </div>
  );
}

export function Tabs(p: P) {
  const tabs = optionsOfTabs(p.tabs);
  const [active, setActive] = useState(() => Math.min(Math.max(0, Math.trunc(n(p.initial))), Math.max(0, tabs.length - 1)));
  const style = ["underline", "pill", "segmented"].includes(p.tabStyle) ? p.tabStyle : "underline";
  return (
    <div className={"studio-tabs is-" + style}>
      <div role="tablist">
        {tabs.map((tab, i) => (
          <button key={i} type="button" role="tab" aria-selected={i === active} onClick={() => setActive(i)}>
            {rt.text(tab.label)}
          </button>
        ))}
      </div>
      <div role="tabpanel">{tabs[active]?.child ?? null}</div>
    </div>
  );
}

function optionsOfTabs(tabs: unknown): P[] {
  const out: P[] = [];
  const walk = (value: unknown) => {
    if (Array.isArray(value)) value.forEach(walk);
    else if (isValidElement(value)) out.push((value as ReactElement<P>).props);
  };
  walk(tabs);
  return out;
}

/** Read by its Tabs; never drawn on its own. */
export function Tab(_: P) {
  return null;
}

// ---------------------------------------------------------------- library
// The Library: components Upskale reviews and pins (Studio's dartLibrary.ts
// is their Flutter side). Both load in the browser only, after the page.

/** A Lottie animation from a web address, played by lottie-web's light player (no expressions). */
export function Lottie(p: P) {
  const box = useRef<HTMLDivElement>(null);
  const [failed, setFailed] = useState(false);
  const src = typeof p.src === "string" && p.src.startsWith("https://") ? p.src : undefined;
  const loop = has(p.loop) ? rt.truthy(p.loop) : true;
  const autoplay = has(p.autoplay) ? rt.truthy(p.autoplay) : true;
  const fit = p.fit === "cover" ? "xMidYMid slice" : p.fit === "fill" ? "none" : "xMidYMid meet";
  useEffect(() => {
    const element = box.current;
    if (!element || !src) return;
    let cancelled = false;
    let animation: { destroy(): void } | undefined;
    setFailed(false);
    import("lottie-web/build/player/lottie_light").then(
      ({ default: lottie }) => {
        if (cancelled) return;
        const played = lottie.loadAnimation({ container: element, renderer: "svg", loop, autoplay, path: src, rendererSettings: { preserveAspectRatio: fit } });
        played.addEventListener("data_failed", () => setFailed(true));
        animation = played;
      },
      () => setFailed(true),
    );
    return () => {
      cancelled = true;
      animation?.destroy();
    };
  }, [src, loop, autoplay, fit]);
  const alt = rt.text(p.alt);
  const style: CSSProperties = { width: has(p.width) ? px(p.width) : "100%", height: has(p.height) ? px(p.height) : 160 };
  if (!src || failed) return <div className="studio-lottie is-missing" style={style} aria-hidden="true" />;
  return <div ref={box} className="studio-lottie" style={style} role={alt ? "img" : undefined} aria-label={alt || undefined} aria-hidden={alt ? undefined : true} />;
}

/** Google's Maps JavaScript API, loaded once with the project's display key. */
function googleMaps(key: string): Promise<any> {
  const w = window as any;
  googleMapsLoading ??= new Promise<void>((resolve, reject) => {
    w.__studioGoogleMaps = () => resolve();
    const script = document.createElement("script");
    script.src = "https://maps.googleapis.com/maps/api/js?key=" + encodeURIComponent(key) + "&loading=async&callback=__studioGoogleMaps";
    script.async = true;
    script.onerror = () => reject(new Error("Google Maps didn't load."));
    document.head.appendChild(script);
  })
    .then(() => Promise.all([w.google.maps.importLibrary("maps"), w.google.maps.importLibrary("marker")]))
    .then(() => w.google.maps)
    .catch((error) => {
      googleMapsLoading = undefined;
      throw error;
    });
  return googleMapsLoading;
}

/** A Google map centred on a point, with markers; onMarkerTap gets the marker as its event. */
export function GoogleMap(p: P) {
  const box = useRef<HTMLDivElement>(null);
  const map = useRef<any>(null);
  const pins = useRef<any[]>([]);
  const info = useRef<any>(null);
  const tap = useRef(p.onMarkerTap);
  tap.current = p.onMarkerTap;
  const [ready, setReady] = useState(0);
  const [failed, setFailed] = useState(false);
  const key = typeof p.apiKey === "string" ? p.apiKey : "";
  const latitude = n(p.latitude);
  const longitude = n(p.longitude);
  const zoom = has(p.zoom) ? n(p.zoom) : 14;
  const mapType = typeof p.mapType === "string" ? p.mapType : "roadmap";
  const interactive = has(p.interactive) ? rt.truthy(p.interactive) : true;
  const markers: P[] = Array.isArray(p.markers) ? p.markers : [];
  const height = has(p.height) ? px(p.height) : 240;
  useEffect(() => {
    if (!key || !box.current) return;
    let cancelled = false;
    googleMaps(key).then(
      (maps) => {
        if (cancelled || !box.current) return;
        map.current = new maps.Map(box.current, { center: { lat: latitude, lng: longitude }, zoom, clickableIcons: false });
        info.current = new maps.InfoWindow();
        setReady((count) => count + 1);
      },
      () => setFailed(true),
    );
    return () => {
      cancelled = true;
    };
    // The map is made once; what changes after is set on it below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);
  useEffect(() => {
    map.current?.setOptions({
      center: { lat: latitude, lng: longitude },
      zoom,
      mapTypeId: mapType,
      gestureHandling: interactive ? "auto" : "none",
      disableDefaultUI: !interactive,
    });
  }, [ready, latitude, longitude, zoom, mapType, interactive]);
  const placed = JSON.stringify(markers.map((marker) => [n(marker.latitude), n(marker.longitude), rt.text(marker.id), rt.text(marker.title)]));
  useEffect(() => {
    const target = map.current;
    if (!target) return;
    const maps = (window as any).google.maps;
    for (const pin of pins.current) pin.setMap(null);
    pins.current = markers.map((marker) => {
      const event = { id: rt.text(marker.id), title: rt.text(marker.title), latitude: n(marker.latitude), longitude: n(marker.longitude) };
      const pin = new maps.Marker({ map: target, position: { lat: event.latitude, lng: event.longitude }, title: event.title || undefined });
      pin.addListener("click", () => {
        if (event.title) {
          // Text, never markup: a title can come from anyone's data.
          const label = document.createElement("span");
          label.textContent = event.title;
          info.current?.setContent(label);
          info.current?.open({ map: target, anchor: pin });
        }
        tap.current?.(event);
      });
      return pin;
    });
    // markers is read through placed: the same markers aren't placed again.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ready, placed]);
  if (!key || failed)
    return (
      <div className="studio-map-unavailable" style={{ height }}>
        Map unavailable
      </div>
    );
  return <div ref={box} className="studio-google-map" style={{ height }} />;
}

css.header:
/* Generated by Upskale Studio. Do not edit this file directly.
   The widgets' look: the Studio preview's, in this project's theme
   (theme.css's --studio-* variables). */

rules.code:
html,
body {
  margin: 0;
  padding: 0;
  background: var(--studio-background);
  color: var(--studio-text);
  font-family: var(--studio-font);
  font-size: var(--studio-font-size);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

h1,
h2,
h3,
h4,
h5,
h6,
p {
  margin: 0;
}

.studio-scaffold {
  display: flex;
  flex-direction: column;
  height: 100dvh;
  background: var(--studio-background);
}

.studio-scaffold-body {
  flex: 1 1 0;
  min-height: 0;
  min-width: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.studio-scroll {
  height: 100%;
  width: 100%;
  min-width: 0;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.studio-scroll.is-horizontal {
  height: auto;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}

.studio-expanded {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.studio-stack {
  position: relative;
  display: grid;
  isolation: isolate;
  min-width: 0;
}

.studio-tap {
  appearance: none;
  border: 0;
  background: none;
  font: inherit;
  color: inherit;
  text-align: inherit;
  cursor: pointer;
  padding: 0;
  margin: 0;
  width: 100%;
}

@keyframes studio-animate-in {
  from {
    opacity: 0;
    transform: translate(var(--studio-animate-x), var(--studio-animate-y)) scale(var(--studio-animate-scale));
  }
}

.studio-text {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: inherit;
  font-weight: inherit;
}

h1.studio-text,
h2.studio-text,
h3.studio-text,
h4.studio-text,
h5.studio-text,
h6.studio-text {
  font-size: inherit;
  font-weight: inherit;
}

.studio-image {
  display: block;
  max-width: 100%;
  min-width: 0;
  object-fit: cover;
  background: var(--studio-surfaceAlt);
  opacity: 0;
  transition: opacity 220ms ease-out;
}

.studio-image.is-missing {
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
  color: var(--studio-textMuted);
  font-size: 28px;
}

.studio-badge {
  display: inline-block;
  align-self: flex-start;
  max-width: 100%;
  padding: 3px 8px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--studio-tone) 40%, transparent);
  background: color-mix(in srgb, var(--studio-tone) 12%, transparent);
  color: var(--studio-tone);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.studio-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 32px;
  padding: 10px 14px;
  border: 1px solid transparent;
  border-radius: var(--studio-button-radius);
  font-size: var(--studio-button-font-size);
  font-weight: 600;
  line-height: 1.2;
  cursor: pointer;
  background: var(--studio-primary);
  color: var(--studio-primaryInk);
  white-space: nowrap;
  max-width: 100%;
  transition: filter 120ms ease;
}

.studio-button.is-secondary {
  background: var(--studio-surface);
  color: var(--studio-text);
  border-color: var(--studio-border);
}

.studio-unavailable {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 16px;
  border-radius: 12px;
  border: 1px solid var(--studio-border);
  background: var(--studio-surfaceAlt);
}

.studio-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.studio-input {
  width: 100%;
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid var(--studio-border);
  border-radius: 9px;
  background: var(--studio-surface);
  color: var(--studio-text);
  font-size: 14px;
}

.studio-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  cursor: pointer;
}

.studio-drawer-scrim {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(15, 17, 21, 0.42);
  cursor: default;
  animation: studio-fade 160ms ease-out both;
}

.studio-drawer {
  position: absolute;
  top: 0;
  bottom: 0;
  max-width: 85%;
  overflow-y: auto;
  background: var(--studio-surface);
  color: var(--studio-text);
  box-shadow: 0 0 32px rgba(15, 17, 21, 0.22);
}

.studio-drawer.is-bottom {
  top: auto;
  left: 0;
  right: 0;
  max-width: none;
  max-height: 85%;
  border-radius: 16px 16px 0 0;
  animation: studio-from-bottom 240ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.studio-carousel-track {
  display: flex;
  overflow-x: auto;
  scrollbar-width: none;
}

.studio-carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 12px;
}

.studio-carousel-controls > button {
  padding: 2px 10px;
  border: 1px solid var(--studio-border);
  border-radius: 999px;
  background: var(--studio-surface);
  cursor: pointer;
}

.studio-carousel-dots button {
  width: 6px;
  height: 6px;
  padding: 0;
  border: 0;
  border-radius: 3px;
  background: var(--studio-border);
  transition: width 160ms ease;
  cursor: pointer;
}

.studio-tabs [role="tablist"] {
  display: flex;
  gap: 2px;
  margin-bottom: 12px;
  overflow-x: auto;
}

.studio-tabs [role="tab"] {
  padding: 8px 12px;
  border: 0;
  background: none;
  color: var(--studio-textMuted);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
}

.studio-tabs.is-segmented [role="tablist"] {
  display: inline-flex;
  padding: 3px;
  border-radius: 10px;
  background: var(--studio-surfaceAlt);
}

.studio-map iframe {
  width: 100%;
  border: 1px solid var(--studio-border);
  border-radius: 12px;
}

.studio-location {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
}

.studio-location-choice {
  align-self: stretch;
  justify-content: flex-start;
  text-align: left;
  white-space: normal;
}

.studio-location-point {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  font-size: 14px;
}

.studio-notices {
  position: fixed;
  left: 50%;
  bottom: calc(24px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(420px, calc(100vw - 32px));
  pointer-events: none;
}

.studio-notice {
  padding: 12px 16px;
  border-radius: 10px;
  background: #2b2d31;
  color: #fff;
  font-size: 14px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
  animation: studio-notice-in 180ms ease-out both;
}

.studio-google-map {
  width: 100%;
  overflow: hidden;
  border: 1px solid var(--studio-border);
  border-radius: 12px;
}

.studio-map-unavailable {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  border: 1px dashed var(--studio-border);
  border-radius: 12px;
  font-size: 13px;
  opacity: 0.7;
}
